window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q07"]=window.__LIBQ["pham-nhan-tu-tien"]["q07"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q07"]["map"]={"updatedAt":"2026-07-22","count":199,"nodes":[{"id":"cuc-bac-dai-tan","name":"Cực bắc Đại Tấn","cn":"","capDo":"vuc","parentId":"dai-tan","blurb":"Khu vực cực bắc của Đại Tấn, nơi đặt Hư Linh điện.","detail":"Đây là điểm xuất phát của lần truyền tống đường dài đưa Hàn Lập, Băng phượng và các trợ lực từ Hư Linh điện tới Hư Thiên điện tại Loạn Tinh Hải.","theLucLienQuan":["Tiểu Cực cung"],"nguon":["@c1121"]},{"id":"thach-phong-kin-trong-hu-thien-dien","name":"Thạch phòng kín trong Hư Thiên điện","cn":"","capDo":"khac","parentId":"hu-thien-dien","blurb":"Phòng truyền tống kín nằm trong nội điện Hư Thiên điện.","detail":"Căn phòng không có cửa, bốn vách bóng loáng mang cấm chế ngăn thần niệm và phản lại kiếm khí. Băng phượng dùng khe không gian rời đi, còn nhân hình Khôi lỗi phá một góc vách để Hàn Lập thoát sang đại sảnh.","theLucLienQuan":[],"nguon":["@c1121"]},{"id":"cu-thap-da-nam-tang-hu-thien-dien","name":"Cự tháp đá năm tầng của nội điện Hư Thiên điện","cn":"","capDo":"khac","parentId":"hu-thien-dien","blurb":"Cự tháp năm tầng thuộc nội điện Hư Thiên điện, có hệ thống thông đạo đá chia bốn hướng.","detail":"Hàn Lập nhận ra nơi này nhờ cửa đá và ngã tư thông đạo quen thuộc. Trong thời điểm hiện tại, các Khôi Lỗi tuần tra, cấm chế, cơ quan và bẫy rập thường thấy đều không hoạt động.","theLucLienQuan":[],"nguon":["@c1121"]},{"id":"hu-thien-dien","name":"Hư Thiên Điện","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian cổ bị nhiều tầng cấm chế phong tỏa, khiến Hàn Lập và Băng Phượng phải liên thủ tìm cách thoát ra.","detail":"Các cấm chế của Hư Thiên Điện không thể bị hai người cưỡng ép phá bỏ. Băng Phượng nhận định việc phá cấm chế theo cách trực tiếp cần ít nhất hai hoặc ba tu sĩ Hóa Thần kỳ.","theLucLienQuan":[],"nguon":["@c1122"]},{"id":"han-ly-thai","name":"Hàn Ly thai","cn":"","capDo":"khac","parentId":"tang-nam-cu-thap","blurb":"Thạch thai tại tầng năm cự tháp, từng là nơi cất giữ Hư Thiên Đỉnh.","detail":"Hàn Ly thai có một tế đàn ở trung tâm và dấu tích của trận đại chiến trước đây. Bên dưới khu vực này ẩn một pháp trận gần như bao phủ toàn bộ thạch thai.","theLucLienQuan":["Tiểu Cực Cung","Băng Phượng nhất tộc"],"nguon":["@c1122"]},{"id":"tang-nam-cu-thap","name":"Tầng năm cự tháp","cn":"","capDo":"khac","parentId":"cu-thap-da-nam-tang-hu-thien-dien","blurb":"Tầng cao nhất của cự tháp đá trong nội điện Hư Thiên Điện.","detail":"Hàn Lập xem đây là khu vực quan trọng nhất của cự tháp và dành hai ngày tìm kiếm nơi khống chế pháp trận. Hàn Ly thai nằm tại tầng này.","theLucLienQuan":[],"nguon":["@c1122"]},{"id":"bang-lan-dao","name":"Băng Lan đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Địa bàn sinh sống của Băng Phượng nhất tộc.","detail":"Trên đảo có một tòa thạch thai được Băng Phượng mô tả là tương tự Hàn Ly thai trong Hư Thiên Điện.","theLucLienQuan":["Băng Phượng nhất tộc"],"nguon":["@c1122"]},{"id":"tang-bao-that","name":"Tàng bảo thất","cn":"","capDo":"khac","parentId":"cu-thap-da-nam-tang-hu-thien-dien","blurb":"Các gian phòng có cửa đá nằm trong mê cung của cự tháp.","detail":"Hàn Lập phá cửa đá và lục soát các tàng bảo thất nhưng không thu được bảo vật. Những vật còn lại bị cấm chế cố định mà hắn chưa thể hóa giải.","theLucLienQuan":[],"nguon":["@c1122"]},{"id":"thach-dai-phap-tran","name":"Thạch đài pháp trận","cn":"","capDo":"khac","parentId":"cu-thap-da-nam-tang-hu-thien-dien","blurb":"Thạch đài đặt pháp trận khống chế khổng lồ của Hư Thiên điện.","detail":"Trung tâm pháp trận có đồ án tương ứng với Hư Thiên Đỉnh. Hàn Lập và Băng Phượng thử dùng bảo đỉnh kích hoạt đại trận tại đây nhưng phải dừng lại vì lượng pháp lực cần thiết quá lớn.","theLucLienQuan":["Hư Thiên điện"],"nguon":["@c1123"]},{"id":"huyen-ngoc-dong","name":"Huyền Ngọc động","cn":"","capDo":"khac","parentId":null,"blurb":"Địa điểm từng được phong ấn bằng cấm chế cùng loại với pháp trận khống chế Hư Thiên điện.","detail":"Hàn Lập nhận ra cấm chế tại Huyền Ngọc động có nguyên lý tương đồng với đại trận trên thạch đài, nhưng đại trận trước mắt lớn hơn khoảng mười lần và thâm ảo hơn nhiều.","theLucLienQuan":["Tiểu Cực Cung"],"nguon":["@c1123"]},{"id":"hai-dao-xuat-hien-thien-trieu","name":"Hải đảo xuất hiện thiên triệu","cn":"","capDo":"khac","parentId":"noi-hai","blurb":"Một cự đảo có thành trì, hải cảng phồn thịnh và dãy lầu các đá trên ngọn núi cao nhất.","detail":"Các phía của thành trì được cấm chế che phủ, chỉ khu vực cảng dùng làm lối ra vào. Ngoài khơi đảo xuất hiện mây rực rỡ, linh áp mạnh, sóng cao hơn trăm trượng và bóng một cung điện trắng giữa không gian vặn vẹo.","theLucLienQuan":["Tông môn trên đảo Nội Hải"],"nguon":["@c1124"]},{"id":"noi-hai","name":"Nội Hải","cn":"","capDo":"vuc","parentId":null,"blurb":"Hải vực có hai mươi sáu đảo nhỏ đang bị Tinh Cung và Nghịch Tinh Minh tranh chấp.","detail":"Nghịch Tinh Minh chiếm hơn hai mươi đảo nhỏ tại Nội Hải, còn Tinh Cung giữ ưu thế về số lần thắng trong các cuộc giao chiến.","theLucLienQuan":["Tinh Cung","Nghịch Tinh Minh"],"nguon":["@c1124","@c1199"]},{"id":"thien-tinh-dao","name":"Thiên Tinh đảo","cn":"","capDo":"khac","parentId":"noi-hai","blurb":"Căn cứ gắn với Thiên Tinh Song Thánh và sức mạnh của Nguyên Từ Thần Quang.","detail":"Thiên Tinh Song Thánh gần như bất bại khi ở phụ cận Thiên Tinh đảo, nhưng không thể rời đảo lâu vì tu vi sẽ giảm mạnh.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1124"]},{"id":"cung-dien-trang-trong-di-tuong","name":"Cung điện trắng trong dị tượng","cn":"","capDo":"khac","parentId":"hai-dao-xuat-hien-thien-trieu","blurb":"Một kiến trúc trắng noãn hiện ra mơ hồ giữa thiên tượng ngoài khơi.","detail":"Cung điện chỉ lộ một góc trong vùng không gian bị vặn vẹo, ở trạng thái như ẩn như hiện và tỏa ánh sáng trong suốt nhàn nhạt. Nguồn gốc cùng bản chất của kiến trúc chưa được xác nhận.","theLucLienQuan":[],"nguon":["@c1124"]},{"id":"dao-do-hoang-sa-mon-quan-ly","name":"Đảo do Hoàng Sa Môn quản lý","cn":"","capDo":"khac","parentId":"loan-tinh-hai","blurb":"Hòn đảo nằm gần nơi Hư Thiên Điện bất ngờ xuất hiện tại Loạn Tinh Hải.","detail":"Trên đảo có lầu các nơi Cam Lâm và ba môn nhân theo dõi dị biến. Hàn Lập bay về phía đảo sau khi Băng Phượng rời đi và được Cam Lâm ra nghênh đón.","theLucLienQuan":["Hoàng Sa Môn"],"nguon":["@c1125"]},{"id":"kho-mon-dao","name":"Khổ Môn Đảo","cn":"","capDo":"khac","parentId":"noi-hai","blurb":"Một đảo nhỏ do Hoàng Sa Môn độc chiếm, nơi Hàn Lập dừng chân hỏi thăm tình hình Loạn Tinh Hải.","detail":"Khổ Môn Đảo có thành thị phàm nhân, bến cảng và một linh sơn đặt quần thể cung điện của Hoàng Sa Môn. Tại đây, Hàn Lập trao đổi hai cổ bảo lấy vật tư và cao giai linh thạch trước khi tiếp tục hành trình.","theLucLienQuan":["Hoàng Sa Môn"],"nguon":["@c1126"]},{"id":"dang-tinh-dao","name":"Đăng Tinh Đảo","cn":"","capDo":"khac","parentId":"noi-hai","blurb":"Một trong thập nhị tinh đảo của Loạn Tinh Hải, nằm về phía bắc Khổ Môn Đảo.","detail":"Đăng Tinh Đảo cách Khổ Môn Đảo vài trăm vạn dặm về phía bắc. Thông tin về vị trí của đảo giúp Hàn Lập đối chiếu hải vực đồ và xác định lộ trình tới Thiên Tinh Thành.","theLucLienQuan":[],"nguon":["@c1126"]},{"id":"thanh-son-thien-tinh-thanh","name":"Thánh Sơn Thiên Tinh Thành","cn":"","capDo":"khac","parentId":"thien-tinh-thanh","blurb":"Thánh Sơn nằm trong Thiên Tinh Thành. Bên dưới núi có động quật nơi hai nhân vật bí ẩn tiếp nhận mật báo của Lăng Ngọc Linh.","detail":"Trong động quật xám xịt dưới Thánh Sơn, một nam tử phục hồi hỏa cầu truyền tin đã bị Hàn Lập phá và cùng một nữ tử bàn về việc chiêu mộ hắn cho Tinh Cung.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1128"]},{"id":"ngoai-hai","name":"Ngoại hải","cn":"","capDo":"vuc","parentId":"loan-tinh-hai","blurb":"Ngoại hải là điểm đến Hàn Lập muốn tới bằng truyền tống trận của Tinh Cung. Chiến sự khiến phần lớn các pháp trận dẫn tới khu vực này bị đóng.","detail":"Tinh Cung chỉ giữ lại hai tòa truyền tống trận đi ngoại hải và yêu cầu quyền sử dụng phù hợp nhằm ngăn tu sĩ Nghịch Tinh Minh lẻn vào.","theLucLienQuan":["Tinh Cung","Nghịch Tinh Minh"],"nguon":["@c1128","@c1216"]},{"id":"nguyen-tu-son","name":"Nguyên Từ Sơn","cn":"","capDo":"khac","parentId":null,"blurb":"Ngọn núi gắn liền với việc tu luyện và phát huy uy lực của Nguyên Từ Thần Quang.","detail":"Cát Thiên Lôi và nữ tử bí ẩn từng tiếp tục tu luyện Nguyên Từ Thần Quang tại đây. Trong phạm vi bao phủ của Nguyên Từ Sơn, nữ tử tin rằng có thể áp chế mạnh bảo vật ngũ hành và đối phó cả tu sĩ Nguyên Anh hậu kỳ, nhưng việc tiếp tục tu luyện cũng có thể khiến Ngũ Hành chi lực trong cơ thể phát tác và gây nổ tan xác.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1129"]},{"id":"ngan-sa-dao","name":"Ngân Sa đảo","cn":"","capDo":"khac","parentId":"ngoai-hai","blurb":"Hải đảo được nhóm họ Điền chọn làm điểm đến để tìm mua nội đan Bạch Ương Ngư Yêu.","detail":"Nơi này vừa phát hiện khoáng mạch cao giai nên thu hút nhiều tu sĩ hải ngoại, khiến Điền đạo hữu cho rằng có cơ hội tìm được yêu đan cần thiết để cứu con.","theLucLienQuan":[],"nguon":["@c1130","@c1151"]},{"id":"tinh-thanh","name":"Tinh Thành","cn":"","capDo":"thanh","parentId":"thien-tinh-dao","blurb":"Thành trì thuộc địa bàn Tinh Cung, nơi Hàn Lập gặp Ôn Thanh trước khi đi hải ngoại.","detail":"Hàn Lập và Ôn Thanh đối diện nhau tại đây trong tình thế đôi bên cùng kiêng kỵ. Sau khi hòa hoãn, Hàn Lập sử dụng truyền tống trận của Tinh Cung để rời thành.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1131"]},{"id":"bai-da-tren-dinh-nui-hai-ngoai","name":"Bãi đá trên đỉnh núi hải ngoại","cn":"","capDo":"khac","parentId":"ngoai-hai","blurb":"Bãi đá trên một đỉnh núi hiểm trở ở hải ngoại, nằm bên ngoài thạch thất chứa đầu truyền tống trận.","detail":"Địa điểm được các vách đá đen bao quanh; thạch thất truyền tống rộng khoảng mười trượng nằm tại đây.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1132"]},{"id":"dong-quat-thanh-son","name":"Động quật Thánh sơn","cn":"","capDo":"khac","parentId":"thanh-son-thien-tinh-thanh","blurb":"Động quật trong Thánh sơn, nơi Thiên Tinh Song Thánh bế quan.","detail":"Ôn Thanh và phu quân trao đổi tại đây về cảnh giới, Hư Thiên Đỉnh và mức độ nguy hiểm của Hàn Lập sau khi hắn rời Thiên Tinh Thành.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1132"]},{"id":"thanh-son","name":"Thánh Sơn","cn":"","capDo":"khac","parentId":"thien-tinh-dao","blurb":"Nơi đặt động phủ mà Thiên Tinh Song Thánh dùng để bí mật thương nghị.","detail":"Trong động phủ tại Thánh Sơn, Ôn Thanh và phu quân bàn cách lôi kéo, gài bẫy hoặc tiêu diệt Hàn Lập.","theLucLienQuan":["Tinh Cung","Thiên Tinh Song Thánh"],"nguon":["@c1133"]},{"id":"nha-go-thanh-tinh","name":"Nhà gỗ thanh tĩnh","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Hàn Lập khám kỳ độc cho Điền Cầm Nhi.","detail":"Tại đây, Hàn Lập phát hiện kỳ độc trong cơ thể Điền Cầm Nhi và nhận ra những dấu hiệu khiến hắn liên tưởng tới Tân Như Âm.","theLucLienQuan":[],"nguon":["@c1133"]},{"id":"bich-linh-dao","name":"Bích Linh Đảo","cn":"","capDo":"khac","parentId":"ngoai-hai","blurb":"Hải đảo nằm rất xa về phía bắc Ngân Sa đảo, nổi tiếng nhờ khoáng mạch có phần lớn linh thạch mang thuộc tính Mộc.","detail":"Nơi đây vốn là một đảo hoang vô danh có diện tích rộng và từng có yêu thú chiếm cứ. Sau khi khoáng mạch linh thạch được phát hiện, đảo mang tên Bích Linh Đảo; tài nguyên trung và cao giai trên đảo bị yêu thú biển, Thiên Tinh Cung cùng Nghịch Tinh Minh phân chia.","theLucLienQuan":["Thiên Tinh Cung","Nghịch Tinh Minh"],"nguon":["@c1135","@c1155","@c1208"]},{"id":"cac-tieu-dao-phu-can-bich-linh-dao","name":"Các tiểu đảo phụ cận Bích Linh Đảo","cn":"","capDo":"khac","parentId":"bich-linh-dao","blurb":"Quần đảo phụ cận Bích Linh Đảo phát triển nhờ hoạt động khai thác và tranh chia khoáng mạch linh thạch.","detail":"Nhiều thế lực và tán tu tới đây xây dựng tiểu thành cùng phường thị. Khu vực dần trở thành một nơi cư trú mới của nhân loại tại ngoại hải, đồng thời được Tinh Cung và Nghịch Tinh Minh cân nhắc bố trí thêm Truyền tống trận.","theLucLienQuan":["Thiên Tinh Cung","Nghịch Tinh Minh"],"nguon":["@c1135"]},{"id":"vung-bien-vo-danh","name":"Vùng biển vô danh","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biển nơi một tiểu đảo bị nhấn chìm và diễn ra cuộc giao chiến giữa Quỷ Vụ với cự cầm xuyên qua vết nứt không gian.","detail":"Dị biến bao phủ phạm vi khoảng trăm dặm quanh một tiểu đảo. Tại đây xuất hiện xoáy nước đường kính hơn mười dặm, Quỷ Vụ từ đáy biển, cuồng phong, sóng lớn và vết nứt không gian trên trời; sau cuộc giao chiến, tiểu đảo biến mất và mặt biển trở lại yên tĩnh.","theLucLienQuan":[],"nguon":["@c1136"]},{"id":"am-minh-chi-dia","name":"Âm Minh Chi địa","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Nơi Hàn Lập từng bị Quỷ Vụ cuốn vào và mất sạch pháp lực cùng thần thông.","detail":"Ký ức từng bị Quỷ Vụ đưa vào Âm Minh Chi địa khiến Hàn Lập vẫn đặc biệt kiêng dè loại sương mù này. Khi Quỷ Vụ tái hiện ở vùng biển vô danh, hắn nhận ra ngay nguồn nguy hiểm quen thuộc và chỉ quan sát từ xa.","theLucLienQuan":[],"nguon":["@c1136"]},{"id":"day-bien-noi-quy-vu-xuat-hien","name":"Đáy biển nơi Quỷ vụ xuất hiện","cn":"","capDo":"khac","parentId":"ngoai-hai","blurb":"Vùng đáy biển sâu khoảng năm, sáu nghìn trượng nơi Quỷ vụ từng xuất hiện và Thanh vũ được tìm thấy.","detail":"Đáy biển bằng phẳng, sạch sẽ dị thường, không có san hô, hải tảo hoặc dấu vết yêu thú thường xuyên qua lại. Nhân hình Khôi Lỗi tìm thấy Thanh vũ tại vị trí cách điểm trung tâm vài dặm.","theLucLienQuan":[],"nguon":["@c1137"]},{"id":"loi-khong-dao","name":"Lôi Không Đảo","cn":"","capDo":"khac","parentId":"ngoai-hai","blurb":"Hòn đảo rộng hàng nghìn dặm, có linh mạch tốt, linh dược hiếm và một phường thị lớn gần Bích Linh Đảo.","detail":"Lôi Không Đảo có nhiều núi đồi và khoảng ba bốn vạn tu sĩ sinh sống. Nghịch Tinh Minh, Tinh Cung, Bích Vân Môn cùng các thế lực khác đều quan tâm tới đảo, nhưng cục diện kiềm chế khiến chưa bên nào có thể độc chiếm.","theLucLienQuan":["Nghịch Tinh Minh","Tinh Cung","Bích Vân Môn","Thanh Dương Môn"],"nguon":["@c1138"]},{"id":"tieu-thanh-loi-khong-dao","name":"Tiểu thành Lôi Không Đảo","cn":"","capDo":"thanh","parentId":"loi-khong-dao","blurb":"Tiểu thành mới xây ở khu vực trung tâm Lôi Không Đảo, nơi tập trung hơn phân nửa số tu sĩ trên đảo.","detail":"Thành rộng khoảng mười dặm, phần lớn kiến trúc làm bằng đá xám trắng. Phường thị nằm về phía nam thành, còn tám thạch tháp quanh thành vận hành đại trận phòng hộ.","theLucLienQuan":[],"nguon":["@c1138"]},{"id":"tam-thach-thap-loi-khong-dao","name":"Tám thạch tháp Lôi Không Đảo","cn":"","capDo":"khac","parentId":"tieu-thanh-loi-khong-dao","blurb":"Tám thạch tháp cao khoảng năm sáu chục trượng, đóng vai trò trận điểm bảo vệ tiểu thành.","detail":"Mặt ngoài mỗi tháp khắc nhiều ký hiệu pháp trận và luôn có tu sĩ Trúc Cơ trấn giữ. Khi được phát động, hệ thống này vận hành đại trận có uy lực không kém trấn phái đại trận của các đại tông môn.","theLucLienQuan":[],"nguon":["@c1138"]},{"id":"tieu-thanh-bich-linh-dao","name":"Tiểu thành trên Bích Linh Đảo","cn":"","capDo":"thanh","parentId":"bich-linh-dao","blurb":"Tiểu thành trên Bích Linh Đảo có khu giao dịch đông đúc tập trung ở phía nam.","detail":"Khu phía nam có nhiều lầu các cao từ hai đến năm tầng, tập trung đông tu sĩ và hoạt động giao dịch náo nhiệt hơn các khu vực khác.","theLucLienQuan":["Lục Liên Điện","Nghịch Tinh Minh"],"nguon":["@c1139"]},{"id":"phuong-thi-phia-nam-tieu-thanh","name":"Phường thị phía nam tiểu thành","cn":"","capDo":"khac","parentId":"tieu-thanh-bich-linh-dao","blurb":"Khu giao dịch náo nhiệt nằm ở phía nam tiểu thành trên Bích Linh Đảo.","detail":"Nhiều tu sĩ cảnh giác ra vào các lầu các trong phường thị. Sáu tiểu điện mang cờ hiệu khác nhau của Lục Liên Điện nằm liền nhau tại một ngã tư.","theLucLienQuan":["Lục Liên Điện","Nghịch Tinh Minh"],"nguon":["@c1139"]},{"id":"thach-thanh","name":"Thạch thành","cn":"","capDo":"thanh","parentId":"linh-dao","blurb":"Thành trì có phường thị và nhiều cửa hàng trên một linh đảo.","detail":"Ban đêm, các nơi trong thành được nguyệt quang thạch chiếu sáng, còn tám thạch tháp kích hoạt tầng lam quang để phòng yêu thú biển tập kích. Việc ra vào thành chịu sự kiểm soát của thủ vệ và cấm chế hộ thành.","theLucLienQuan":["Lục Liên Điện"],"nguon":["@c1140"]},{"id":"khe-nui-ngoai-thach-thanh","name":"Khe núi ngoài Thạch thành","cn":"","capDo":"khac","parentId":"linh-dao","blurb":"Khe núi vắng vẻ nằm ngoài Thạch thành, có mây mù và hơi nước dày.","detail":"Hàn Lập chọn nơi này để bố trí trận pháp ẩn nấp, sau đó điều khiển hàng ngàn Phệ Kim Trùng mang thần niệm tỏa đi giám sát khu vực.","theLucLienQuan":[],"nguon":["@c1140"]},{"id":"linh-dao","name":"Linh đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Hòn đảo nơi Thạch thành tọa lạc.","detail":"Ban đêm, tu sĩ trên đảo tăng cường phòng ngự vì vùng biển lân cận có yêu thú tinh thông ẩn nấp và có thể bất ngờ tập kích.","theLucLienQuan":[],"nguon":["@c1140"]},{"id":"ly-long-dao","name":"Ly Long đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Hải đảo được Hoàng Côn nhắc tới như nơi mình xuất thân.","detail":"Chương chỉ xác nhận mối liên hệ giữa Hoàng Côn và Ly Long đảo, chưa mô tả vị trí, địa hình hoặc phạm vi của đảo.","theLucLienQuan":["Ly Long đảo"],"nguon":["@c1141"]},{"id":"ngon-nui-da-trung-tam","name":"Ngọn núi đá trung tâm","cn":"","capDo":"khac","parentId":"bich-linh-dao","blurb":"Khu vực trọng yếu của Nghịch Tinh Minh trên Bích Linh Đảo.","detail":"Ngọn núi được cấm đoạn đại trận màu lam bao phủ và canh phòng nghiêm mật. Quý Tân các cùng Vân Yên điện nằm ở khu vực phía trên núi.","theLucLienQuan":["Nghịch Tinh Minh"],"nguon":["@c1143"]},{"id":"quy-tan-cac","name":"Quý Tân các","cn":"","capDo":"khac","parentId":"ngon-nui-da-trung-tam","blurb":"Nơi tiếp đãi khách được triệu tập tới Bích Linh Đảo.","detail":"Tráng hán đề nghị Phí tiền bối nghỉ lại đây một đêm trước khi dự cuộc hội họp vào ngày hôm sau.","theLucLienQuan":["Nghịch Tinh Minh"],"nguon":["@c1143"]},{"id":"van-yen-dien","name":"Vân Yên điện","cn":"","capDo":"khac","parentId":"ngon-nui-da-trung-tam","blurb":"Địa điểm tổ chức cuộc hội họp của Nghịch Tinh Minh tại Bích Linh Đảo.","detail":"Phí tiền bối được hẹn tới đây vào hôm sau để gặp Đường trưởng lão và các tu sĩ đã được triệu tập.","theLucLienQuan":["Nghịch Tinh Minh"],"nguon":["@c1143"]},{"id":"dao-nho-cua-nghich-tinh-minh","name":"Đảo nhỏ của Nghịch Tinh Minh","cn":"","capDo":"khac","parentId":"loan-tinh-hai","blurb":"Hòn đảo tập trung lực lượng đông đảo của Nghịch Tinh Minh và là nơi Cực Âm Tổ Sư tạm trú.","detail":"Trên đảo có khoảng năm sáu trăm tu sĩ, phần lớn đạt từ Trúc Cơ kỳ trở lên và có vài tu sĩ Nguyên Anh tọa trấn. Nơi ở bí mật của Cực Âm nằm dưới ngọn núi đá trên đảo.","theLucLienQuan":["Nghịch Tinh Minh"],"nguon":["@c1144"]},{"id":"dinh-nui-da","name":"Đỉnh núi đá","cn":"","capDo":"khac","parentId":"dao-nho-cua-nghich-tinh-minh","blurb":"Đỉnh núi rộng trên đảo nhỏ của Nghịch Tinh Minh, nơi đặt lầu hắc thạch che giấu chỗ ở của Cực Âm.","detail":"Bề mặt đỉnh núi rộng nhưng có ít kiến trúc. Tòa lầu hắc thạch năm tầng và lối xuống lòng núi được bố trí tại đây.","theLucLienQuan":["Nghịch Tinh Minh"],"nguon":["@c1144"]},{"id":"lau-cac-hac-thach","name":"Lầu các hắc thạch","cn":"","capDo":"khac","parentId":"dinh-nui-da","blurb":"Tòa lầu năm tầng xây bằng quái thạch đen trên đỉnh núi đá.","detail":"Tầng dưới của lầu rộng hàng trăm trượng và toàn bộ kiến trúc được âm khí đen xám bao phủ. Các tầng nổi gần như trống rỗng, chỉ có một đệ tử Kết Đan của Cực Âm canh giữ, còn lối bí mật dẫn xuống lòng núi nằm phía dưới.","theLucLienQuan":["Nghịch Tinh Minh"],"nguon":["@c1144"]},{"id":"thong-dao-duoi-lau","name":"Thông đạo dưới lầu","cn":"","capDo":"khac","parentId":"lau-cac-hac-thach","blurb":"Thông đạo hắc thạch bí mật kéo dài từ dưới lầu vào sâu trong lòng núi.","detail":"Cầu thang hắc thạch dài hàng trăm trượng được bảo vệ bằng màn sáng và cấm chế ngăn thần niệm. Thông đạo dẫn tới khu vực có linh khí tinh thuần hơn cực phẩm linh thạch và thạch thất của Cực Âm.","theLucLienQuan":["Nghịch Tinh Minh"],"nguon":["@c1144"]},{"id":"thach-that-cua-cuc-am","name":"Thạch thất của Cực Âm","cn":"","capDo":"khac","parentId":"thong-dao-duoi-lau","blurb":"Thạch thất nằm cuối thông đạo dưới lòng núi, là nơi ẩn náu của Cực Âm Tổ Sư.","detail":"Cực Âm dùng âm hỏa tra tấn một Nguyên Anh màu vàng tại đây. Hàn Lập phá cửa xông vào, khiến hai người tái ngộ và lập tức bắt đầu giao thủ.","theLucLienQuan":["Nghịch Tinh Minh"],"nguon":["@c1144"]},{"id":"ngoc-that","name":"Ngọc thất","cn":"","capDo":"khac","parentId":"thach-that-cua-cuc-am","blurb":"Gian phòng nơi Hàn Lập giao chiến và bắt giữ Cực Âm Tổ Sư.","detail":"Ngọc thất có cấm chế hạn chế thần thức nhưng cấm chế không phát huy tác dụng trong trận chiến. Kiền Lam Băng Diễm phủ gian phòng thành một vùng băng giá, còn Hư Thiên Đỉnh tạo màn chắn phong kín cửa đá.","theLucLienQuan":[],"nguon":["@c1145"]},{"id":"mat-that-duoi-gian-lau","name":"Mật thất dưới Giản Lâu","cn":"","capDo":"khac","parentId":"gian-lau","blurb":"Mật thất nằm dưới Giản Lâu, nối với lầu qua mật môn và thông đạo ngầm. Đây là nơi Man Hồ Tử báo thù rồi tọa hóa.","detail":"Man Hồ Tử cắn nuốt Nguyên Anh Cực Âm Tổ Sư, truyền âm vị trí động phủ cho Hàn Lập rồi tan biến tại đây. Hàn Lập sau đó phá nát và thiêu hủy thân xác Cực Âm trước khi rời mật thất.","theLucLienQuan":["Nghịch Tinh Minh"],"nguon":["@c1147"]},{"id":"gian-lau","name":"Giản Lâu","cn":"","capDo":"khac","parentId":"thiet-thach-phong","blurb":"Lầu các tại Thiết Thạch Phong, có mật môn dẫn xuống thông đạo và mật thất dưới đất. Hàn Lập trở lại tầng một đúng lúc bên ngoài phát sinh biến loạn.","detail":"Một tu sĩ Kết Đan của Nghịch Tinh Minh xông vào đây báo tin yêu thú tập kích rồi bị Hàn Lập giết. Từ cửa lầu, Hàn Lập ẩn giấu hành tung để quan sát chiến trường.","theLucLienQuan":["Nghịch Tinh Minh"],"nguon":["@c1147"]},{"id":"thiet-thach-phong","name":"Thiết Thạch Phong","cn":"","capDo":"khac","parentId":"loan-tinh-hai","blurb":"Cứ điểm của Nghịch Tinh Minh tại Loạn Tinh Hải. Nơi này bị nhiều Hải tộc hóa hình phát động tập kích để tranh đoạt Đỉnh giai Cực Phẩm Linh Thạch.","detail":"Chiến trường quanh Thiết Thạch Phong có nhiều nhóm tu sĩ và yêu thú hóa hình giao đấu. Đầu Đà béo đại diện Hải tộc công khai ép Đường tính lão giả giao linh thạch, trong khi đối phương phủ nhận đang sở hữu vật đó.","theLucLienQuan":["Nghịch Tinh Minh","Hải tộc"],"nguon":["@c1147"]},{"id":"dao-linh-quang","name":"Đảo linh quặng","cn":"","capDo":"khac","parentId":"ngoai-hai","blurb":"Hòn đảo nhỏ tại Ngoại hải có mạch khoáng đã khai thác được cực phẩm linh thạch.","detail":"Việc phát hiện ít nhất một khối cực phẩm linh thạch khiến hòn đảo trở thành chiến trường tranh đoạt giữa Hải tộc, Nghịch Tinh Minh và lực lượng Tinh Cung.","theLucLienQuan":["Hải tộc","Nghịch Tinh Minh","Tinh Cung"],"nguon":["@c1148"]},{"id":"thach-linh","name":"Thạch lĩnh","cn":"","capDo":"khac","parentId":"dao-linh-quang","blurb":"Khu vực trọng yếu trên đảo linh quặng, nơi diễn ra trận bao vây giữa Hải tộc và Nghịch Tinh Minh.","detail":"Yêu vụ bao phủ không trung quanh thạch lĩnh, đại quân yêu thú truy sát tu sĩ tháo chạy và thần niệm của Kim Giao Vương quét trọn toàn khu vực.","theLucLienQuan":["Hải tộc","Nghịch Tinh Minh"],"nguon":["@c1148"]},{"id":"lau-cac-tren-thach-phong","name":"Lầu các trên Thạch Phong","cn":"","capDo":"khac","parentId":"thiet-thach-phong","blurb":"Lầu các nằm trên Thạch Phong, nơi diễn ra cuộc giao chiến giữa Kim Giao Vương và Đường tính lão giả.","detail":"Quyền kình và Kim Thương phá thủng lầu các trong lúc Kim Giao Vương truy kích đối thủ. Hàn Lập ẩn gần đại môn của công trình để theo dõi trận chiến và âm thầm tránh một đòn trảo mang.","theLucLienQuan":["Nghịch Tinh Minh"],"nguon":["@c1149"]},{"id":"mo-linh-quang-bich-linh-dao","name":"Mỏ linh quặng Bích Linh Đảo","cn":"","capDo":"khac","parentId":"bich-linh-dao","blurb":"Mỏ linh quặng trên Bích Linh Đảo, chủ yếu sản sinh linh thạch Mộc thuộc tính.","detail":"Hải tộc chiếm quyền kiểm soát mỏ sau khi giết sáu tu sĩ Nguyên Anh. Kim Giao Vương cho rằng trong mỏ vẫn có thể còn cực phẩm linh thạch chưa được khai thác.","theLucLienQuan":["Hải tộc","Nghịch Tinh Minh","Tinh Cung"],"nguon":["@c1151"]},{"id":"hai-vuc-quanh-ngan-sa-dao","name":"Hải vực quanh Ngân Sa đảo","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biển bao quanh Ngân Sa đảo, nơi số lượng yêu thú tăng lên bất thường.","detail":"Trên đường trở về, Hàn Lập không gặp tu sĩ hoạt động trong khu vực này. Sự xuất hiện của nhiều yêu thú và cuộc tập kích vừa xảy ra khiến lực lượng giữ đảo tăng cường phòng bị.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1152"]},{"id":"thanh-tran-tren-ngan-sa-dao","name":"Thành trấn trên Ngân Sa đảo","cn":"","capDo":"thanh","parentId":"ngan-sa-dao","blurb":"Thành trấn nằm bên trong Ngân Sa đảo, cách cửa vào hơn trăm dặm.","detail":"Hơn trăm đệ tử Tinh Cung đóng quân tại đây và có thể nhanh chóng xuất phát chi viện cho cửa đảo khi cần.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1152"]},{"id":"dao-san-ho-vo-danh-phia-bac-tinh-thanh","name":"Đảo san hô vô danh phía bắc Tinh Thành","cn":"","capDo":"khac","parentId":"noi-hai-loan-tinh-hai","blurb":"Hòn đảo san hô cách Tinh Thành khoảng ba nghìn dặm, được Hàn Lập chọn làm nơi gặp Thiên Tinh Song Thánh.","detail":"Hàn Lập đến đảo trước giờ hẹn và dùng thần niệm dò xét cả đáy biển lẫn không trung trong phạm vi hàng trăm dặm. Gần giữa trưa, hai đạo độn quang xuất hiện ở cuối chân trời và bay thẳng về phía đảo.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1153"]},{"id":"noi-hai-loan-tinh-hai","name":"Nội hải Loạn Tinh Hải","cn":"","capDo":"vuc","parentId":"loan-tinh-hai","blurb":"Khu vực nội hải của Loạn Tinh Hải, nơi Hàn Lập trở về bằng Truyền Tống Trận trước cuộc gặp với Thiên Tinh Song Thánh.","detail":"Sau khi rời hòn đảo có Truyền Tống Trận, Hàn Lập trở lại nội hải rồi chuẩn bị tới đảo san hô phía bắc Tinh Thành.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1153"]},{"id":"thuong-co-truyen-tong-tran-noi-loan-tinh-hai-voi-dai-tan","name":"Thượng cổ Truyền Tống Trận nối Loạn Tinh Hải với Đại Tấn","cn":"","capDo":"khac","parentId":"loan-tinh-hai","blurb":"Một Truyền Tống Trận bí mật nối Loạn Tinh Hải với Đại Tấn và nằm dưới sự kiểm soát của Tinh Cung.","detail":"Thiên Tinh Song Thánh từng dùng Truyền Tống Trận này để đến Đại Tấn. Hành trình tới vị trí của trận vẫn có nguy hiểm ngay cả đối với họ, còn Tinh Cung bố trí một trưởng lão trông coi khu vực phụ cận trong thời gian dài.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1154"]},{"id":"ma-ho-dao","name":"Ma Hồ Đảo","cn":"","capDo":"khac","parentId":"noi-tinh-hai","blurb":"Tiểu đảo vô danh nằm gần Nội Tinh Hải, ít cây cối, không có linh mạch và hiếm người lui tới.","detail":"Tên gọi Ma Hồ Đảo bắt nguồn từ hồ nước xanh biếc trên đảo, nơi sản sinh Thúy Đồng. Chỉ một số ít tán tu quanh vùng biết tới hòn đảo này.","theLucLienQuan":["Tán tu Loạn Tinh Hải"],"nguon":["@c1156"]},{"id":"ma-ho","name":"Ma Hồ","cn":"","capDo":"khac","parentId":"ma-ho-dao","blurb":"Hồ nước xanh như phỉ thúy nằm trên Ma Hồ Đảo, là nơi sản sinh Thúy Đồng.","detail":"Nước hồ được kể là có đặc tính khiến phàm nhân rơi xuống vẫn nổi và không chìm. Dưới đáy hồ có cấm chế phức tạp cùng động phủ bị nghi là nơi Man Hồ Tử để lại kho báu.","theLucLienQuan":[],"nguon":["@c1156"]},{"id":"dong-phu-duoi-day-ho","name":"Động phủ dưới đáy hồ","cn":"","capDo":"khac","parentId":"ma-ho-dao","blurb":"Động phủ bảo tàng của Man Hồ Tử nằm dưới hồ nước xanh biếc trên Ma Hồ Đảo.","detail":"Nơi này được bảo vệ bằng cấm chế thâm ảo và trở thành mục tiêu tranh đoạt của ba đệ tử Man Hồ Tử, Kim Hoa Lão Tổ cùng Hàn Lập.","theLucLienQuan":["Môn hạ Man Hồ Tử","Huyết Quang Môn","Mộc Kiếm Các"],"nguon":["@c1157"]},{"id":"con-ngo","name":"Côn Ngô","cn":"","capDo":"khac","parentId":null,"blurb":"Địa danh gắn với Côn Ngô Tam Lão và nguồn gốc của Hàng Ma Trượng.","detail":"Hàng Ma Trượng được nhắc là pháp bảo của Côn Ngô Tam Lão, hiện do Hàn Lập sử dụng với uy lực mạnh hơn trước.","theLucLienQuan":["Côn Ngô Tam Lão"],"nguon":["@c1158"]},{"id":"day-ho-co-dong-phu-man-ho-tu","name":"Đáy hồ có động phủ Man Hồ Tử","cn":"","capDo":"khac","parentId":"ma-ho","blurb":"Khu vực dưới đáy hồ che giấu lối vào động phủ Man Hồ Tử.","detail":"Nơi này có đá ngầm giả, huyễn thuật màu lam và cấm chế Ngũ Hành. Sau khi các lớp che chắn bị phá, một truyền tống trận dẫn vào động phủ hiện ra.","theLucLienQuan":["Môn hạ Man Hồ Tử"],"nguon":["@c1160"]},{"id":"truyen-tong-tran-ti-thuy","name":"Truyền tống trận tị thủy","cn":"","capDo":"khac","parentId":"day-ho-co-dong-phu-man-ho-tu","blurb":"Pháp trận dưới đáy hồ dẫn người sử dụng vào thạch thất trong động phủ Man Hồ Tử.","detail":"Trận pháp có đường kính hơn mười trượng và được luyện bằng vật liệu đặc thù có khả năng ngăn nước hồ. Hàn Lập bố trí Lục Dực Sương Công canh giữ bên ngoài trước khi kích hoạt trận.","theLucLienQuan":["Môn hạ Man Hồ Tử"],"nguon":["@c1160"]},{"id":"dong-phu-man-ho-tu","name":"Động phủ Man Hồ Tử","cn":"","capDo":"khac","parentId":"day-ho-co-dong-phu-man-ho-tu","blurb":"Động phủ bí mật của Man Hồ Tử, được tiếp cận thông qua truyền tống trận dưới đáy hồ.","detail":"Bên trong không còn người ẩn nấp và lưu giữ mấy trăm vạn linh thạch, bảo vật, điển tịch bí thuật cùng một khối Canh Tinh lớn. Hàn Lập thu lấy tàng bảo sau khi dùng thần thức kiểm tra toàn bộ khu vực.","theLucLienQuan":["Môn hạ Man Hồ Tử"],"nguon":["@c1160"]},{"id":"tien-gioi","name":"Tiên giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện được xác định là nguồn gốc của Kim Khuyết Ngọc Thư và các tiên gia chi vật.","detail":"Thiên Lan Thánh Thú phân thân cho biết lực cản cách giới giữa Tiên giới và Linh giới nhỏ hơn lực cản giữa Linh giới và Nhân giới, vì vậy đôi khi tiên gia chi vật có thể lưu lạc xuống Linh giới.","theLucLienQuan":[],"nguon":["@c1162"]},{"id":"nai-tinh-dao","name":"Nại Tinh Đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Hòn đảo lớn được một tầng bạch vụ cấm chế bao phủ.","detail":"Hàn Lập tới Nại Tinh Đảo sau hai tháng di chuyển. Thay vì đi qua bến cảng, hắn chọn một nơi hoang vắng, cưỡng ép xuyên qua cấm chế rồi đi sâu khoảng một nghìn dặm trước khi những tu sĩ trấn thủ tới kiểm tra.","theLucLienQuan":[],"nguon":["@c1163"]},{"id":"co-gia-trang","name":"Cố Gia Trang","cn":"","capDo":"khac","parentId":"nai-tinh-dao","blurb":"Trang viên của Cố gia trên Nại Tinh Đảo, nơi gắn với một đoạn cơ duyên cũ của Hàn Lập.","detail":"Hai đệ tử Trúc Cơ của vợ chồng Văn Tư Nguyệt đang ở tại đây nhờ quan hệ với con trưởng Cố gia. Khi trở lại sau hơn hai trăm năm, Hàn Lập nhận ra trang viên và yêu cầu hậu nhân Cố gia tới gặp mình.","theLucLienQuan":["Cố gia"],"nguon":["@c1163"]},{"id":"chan-tien-gioi","name":"Chân Tiên Giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện được cho là nguồn gốc của Ngân Khoa Văn và Kim Mô Văn.","detail":"Hai loại Tiên gia linh văn được truyền từ Chân Tiên Giới xuống Linh Giới, nơi chúng tiếp tục được nghiên cứu, chỉnh lý và chú giải.","theLucLienQuan":[],"nguon":["@c1163"]},{"id":"dong-phu-gia-dinh-van-tu-nguyet","name":"Động phủ của gia đình Văn Tư Nguyệt","cn":"","capDo":"khac","parentId":"viet-quoc","blurb":"Động phủ nằm sau một Thạch Môn có cấm chế trên sườn ngọn núi nhỏ.","detail":"Hàn Lập lưu lại đây một ngày một đêm để kiểm tra khả năng lĩnh ngộ trận pháp của Điền Cầm Nhi. Vợ chồng Văn Tư Nguyệt cùng các đệ tử cũng tới gặp ông tại đây.","theLucLienQuan":[],"nguon":["@c1164"]},{"id":"linh-quang-quy-linh-mon","name":"Linh quáng Quỷ Linh Môn","cn":"","capDo":"khac","parentId":"viet-quoc","blurb":"Khoáng mạch của Quỷ Linh Môn nằm trong một hạp cốc hoang vu tại Việt Quốc.","detail":"Bên dưới linh quáng là mạng lưới đường hầm dày đặc, nơi phàm nhân khai thác linh thạch dưới sự giám sát của tu sĩ Quỷ Linh Môn. Do tông môn suy yếu, lực lượng trấn giữ tại đây khá mỏng.","theLucLienQuan":["Quỷ Linh Môn"],"nguon":["@c1164"]},{"id":"cam-dia-cu-duoi-linh-quang","name":"Cấm địa cũ dưới linh quáng","cn":"","capDo":"khac","parentId":"linh-quang-quy-linh-mon","blurb":"Khu vực bỏ hoang nằm sâu dưới linh quáng Quỷ Linh Môn, chứa một Thượng cổ Truyền Tống Trận.","detail":"Nơi này từng được Quỷ Linh Môn phái đệ tử chuyên trách trông coi và có quan hệ chưa rõ với Vương Thiền. Phạm sư huynh bị chém đầu tại động quật sau khi dẫn Mạnh sư đệ tới xem Truyền Tống Trận.","theLucLienQuan":["Quỷ Linh Môn"],"nguon":["@c1164"]},{"id":"thien-lo-quoc","name":"Thiên Lô quốc","cn":"","capDo":"quoc-gia","parentId":"thien-nam","blurb":"Quốc gia thuộc Thiên Nam, nơi Huyền Diệu Môn từng đặt tông môn.","detail":"Khoảng tám mươi năm trước, Huyền Diệu Môn tại Thiên Lô quốc bị Hỏa Linh Tông tiêu diệt chỉ trong một đêm.","theLucLienQuan":["Huyền Diệu Môn","Hỏa Linh Tông"],"nguon":["@c1165"]},{"id":"dong-quat-co-truyen-tong-tran","name":"Động quật cổ truyền tống trận","cn":"","capDo":"khac","parentId":"nguyen-vu-quoc","blurb":"Động quật chứa đầu cổ truyền tống trận nối tới Loạn Tinh Hải. Nơi này từng bị Quỷ Linh Môn đục khoét và trùng tu.","detail":"Hàn Lập đánh ngất đại hán họ Mạnh, phá hủy truyền tống trận, sửa ký ức nhân chứng và thiêu các thi thể Ma Diễm Môn tại đây. Trước khi rời đi, hắn phá xuyên phần đỉnh động quật đã được Quỷ Linh Môn trùng tu.","theLucLienQuan":["Quỷ Linh Môn","Ma Diễm Môn"],"nguon":["@c1166"]},{"id":"ngon-nui-cu-cua-tan-nhu-am","name":"Ngọn núi cũ của Tân Như Âm","cn":"","capDo":"khac","parentId":"nguyen-vu-quoc","blurb":"Ngọn núi hẻo lánh gần biên giới Nguyên Vũ Quốc, từng là nơi Tân Như Âm ẩn cư. Địa điểm này về sau trở thành địa bàn của Hóa Vũ Môn.","detail":"Các cấm chế và pháp trận cũ vẫn còn nhưng trúc lâu của Tân Như Âm đã biến mất, thay vào đó là nhiều lầu các và tu sĩ Hóa Vũ Môn. Hàn Lập dùng một hỏa cầu phá thủng cấm chế bao phủ ngọn núi rồi truy hỏi về những cư dân cũ.","theLucLienQuan":["Hóa Vũ Môn"],"nguon":["@c1166"]},{"id":"ngon-nui-to-cu-cua-phung-chi","name":"Ngọn núi tổ cư của Phụng Chí","cn":"","capDo":"khac","parentId":"thien-nam","blurb":"Ngọn núi nơi tổ tiên Phụng Chí từng sinh sống và đoàn tu sĩ Hóa Vũ Môn tạm dừng chân.","detail":"Hóa Vũ Môn sử dụng ngọn núi làm nơi tạm trú trên đường tới Nguyễn Vũ Quốc. Khi biết nơi này từng thuộc về bạn cũ của mình, Hàn Lập yêu cầu toàn bộ tu sĩ đang cư trú phải rời đi.","theLucLienQuan":["Hóa Vũ Môn"],"nguon":["@c1167"]},{"id":"truc-lau-cu-cua-tan-nhu-am","name":"Trúc lâu cũ của Tân Như Âm","cn":"","capDo":"khac","parentId":"ngon-nui-to-cu-cua-phung-chi","blurb":"Nơi ở cũ của Tân Như Âm được di chuyển ra khu rừng trúc phía sau núi và bảo tồn nguyên trạng.","detail":"Phụng Chí cho người gia trì linh quang và quét dọn trúc lâu định kỳ theo lời mẹ mình. Khi tới đây, Điền Cầm Nhi vô thức chạm vào đồ vật và đi lại trong trạng thái mơ màng, khiến Hàn Lập đặt câu hỏi về mối liên hệ giữa nàng với Tân Như Âm qua luân hồi.","theLucLienQuan":[],"nguon":["@c1167"]},{"id":"truc-lau-cua-tan-nhu-am","name":"Trúc lâu của Tân Như Âm","cn":"","capDo":"khac","parentId":"ngon-nui-cu-cua-tan-nhu-am","blurb":"Nơi Tân Như Âm từng cư ngụ và là địa điểm Điền Cầm Nhi nảy sinh cảm thụ kỳ lạ.","detail":"Phản ứng của Điền Cầm Nhi sau một ngày ở trong trúc lâu khiến Hàn Lập tăng mức nghi ngờ nàng là Tân Như Âm chuyển thế.","theLucLienQuan":[],"nguon":["@c1168"]},{"id":"lac-van-tong-son-mon","name":"Lạc Vân Tông","cn":"","capDo":"khac","parentId":"van-mong-son","blurb":"Sơn môn của Lạc Vân Tông trong Vân Mộng Sơn Mạch.","detail":"Đây là điểm đến của Hàn Lập và Điền Cầm Nhi, nơi Hàn Lập dự định chính thức thu nàng làm môn hạ và tiếp đón trưởng lão Cổ Kiếm Môn cùng Bách Xảo Viện.","theLucLienQuan":["Lạc Vân Tông"],"nguon":["@c1168"]},{"id":"dong-bang-cua-nam-cung-uyen","name":"Động băng","cn":"","capDo":"khac","parentId":"lac-van-tong-son-mon","blurb":"Nơi Nam Cung Uyển tiếp tục ở lại khi phong ấn chưa được giải khai.","detail":"Nam Cung Uyển từng tỉnh lại và không gặp nguy hiểm, nhưng vẫn tu luyện một công pháp trong động băng nên chưa thích hợp cưỡng ép giải phong.","theLucLienQuan":["Lạc Vân Tông"],"nguon":["@c1168"]},{"id":"truy-ma-coc","name":"Trụy Ma Cốc","cn":"","capDo":"vuc","parentId":"thien-nam","blurb":"Hiểm địa tại Thiên Nam có ngoại vi đã suy yếu cấm chế nhưng vùng sâu vẫn ẩn chứa ma khí và nguy hiểm.","detail":"Không gian liệt phùng tại ngoại vi đã không còn xuất hiện như trước, khiến nhiều tu sĩ có thể vào tìm bảo vật. Trong vùng sâu, một ma thi hấp thu lượng ma khí còn lại của Cổ Ma và gây ra dị biến.","theLucLienQuan":[],"nguon":["@c1169"]},{"id":"ma-uyen-van-truong","name":"Ma Uyên vạn trượng","cn":"","capDo":"khac","parentId":"truy-ma-coc","blurb":"Vực sâu chứa ma khí trong Trụy Ma Cốc.","detail":"Ma thi vô danh dự định lẻn vào đây để dùng ma khí tiếp tục quán chú thể xác và mưu cầu đột phá Nguyên Anh hậu kỳ.","theLucLienQuan":[],"nguon":["@c1169"]},{"id":"cam-dia-yem-nguyet","name":"Cấm địa Lạc Vân Tông","cn":"","capDo":"khac","parentId":"son-mon-lac-van-tong","blurb":"Cấm địa bên trong Lạc Vân Tông, nơi Nam Cung Uyển ngủ say trong một thạch thất.","detail":"Hàn Lập mở thạch thất tại đây và gặp lại Nam Cung Uyển trong màn băng bích sau khi dung mạo của nàng đã khôi phục.","theLucLienQuan":["Lạc Vân Tông"],"nguon":["@c1169"]},{"id":"son-mon-lac-van-tong","name":"Sơn môn Lạc Vân Tông","cn":"","capDo":"khac","parentId":"thien-nam","blurb":"Sơn môn của Lạc Vân Tông tại Thiên Nam.","detail":"Trấn sơn đại trận được mở bỏ và hàng trăm đệ tử được bố trí nghênh đón Hàn Lập trở về với thân phận đại tu sĩ Nguyên Anh hậu kỳ.","theLucLienQuan":["Lạc Vân Tông"],"nguon":["@c1169"]},{"id":"ngoai-coc-truy-ma-coc","name":"Ngoại cốc Trụy Ma Cốc","cn":"","capDo":"khac","parentId":"truy-ma-coc","blurb":"Khu vực phía ngoài Trụy Ma Cốc, nơi Liễu Ngọc, Mộ Phái Linh và Tống Ngọc tiếp tục tìm Huyễn linh thảo.","detail":"Sau gần nửa tháng tìm kiếm không có kết quả, ba nữ tu quyết định tiến tới những phần chưa dò xét của ngoại cốc. Các khu vực này có thể tồn tại không gian liệt phùng.","theLucLienQuan":["Bạch Phượng Phong"],"nguon":["@c1170"]},{"id":"noi-coc-truy-ma-coc","name":"Nội cốc Trụy Ma Cốc","cn":"","capDo":"vuc","parentId":"truy-ma-coc","blurb":"Khu vực nguy hiểm nằm sâu trong Trụy Ma Cốc, có cổ thú đủ sức đe dọa tu sĩ Nguyên Anh.","detail":"Tống Ngọc, Mộ Phái Linh và Liễu Ngọc chỉ dự định tìm kiếm trong phạm vi vài trăm dặm gần lối vào. Dù có lộ tuyến tương đối an ổn, cả ba vẫn bị một ma tu bí ẩn truy đuổi và bắt sống tại đây.","theLucLienQuan":["Quỷ Linh Môn"],"nguon":["@c1172"]},{"id":"phien-bang-tuyet-thien-dia","name":"Phiến băng tuyết thiên địa","cn":"","capDo":"khac","parentId":"noi-coc-truy-ma-coc","blurb":"Vùng băng tuyết có gió lạnh như cắt nằm bên trong nội cốc.","detail":"Ba nữ tu xuất hiện tại đây sau năm ngày di chuyển qua lộ tuyến tiến vào nội cốc. Họ phải duy trì màn hào quang hộ thân trước khí hậu khắc nghiệt.","theLucLienQuan":[],"nguon":["@c1172"]},{"id":"bang-kinh-thong-dao","name":"Băng kính thông đạo","cn":"","capDo":"khac","parentId":"noi-coc-truy-ma-coc","blurb":"Thông đạo lớn nối vào vùng băng tuyết trong nội cốc.","detail":"Ba nữ tu đi qua thông đạo này theo lộ tuyến do Tử Linh cung cấp. Đây cũng là con đường Hàn Lập và Tử Linh từng theo lực lượng Quỷ Linh Môn đi qua.","theLucLienQuan":["Quỷ Linh Môn"],"nguon":["@c1172"]},{"id":"ngon-nui-xanh-trong-noi-coc","name":"Ngọn núi xanh trong nội cốc","cn":"","capDo":"khac","parentId":"noi-coc-truy-ma-coc","blurb":"Ngọn núi có nhiều linh dược hiếm nằm trong phạm vi thăm dò của ba nữ tu.","detail":"Tống Ngọc, Mộ Phái Linh và Liễu Ngọc chia nhau tìm kiếm quanh núi suốt một ngày một đêm. Họ thu được một số linh dược khác nhưng không tìm thấy Huyễn Linh Thảo.","theLucLienQuan":[],"nguon":["@c1172"]},{"id":"noi-giam-giu-co-cot-da-phat-bach-quang","name":"Nơi giam giữ có cột đá phát bạch quang","cn":"","capDo":"khac","parentId":"noi-coc-truy-ma-coc","blurb":"Không gian lạnh lẽo có nhiều cột đá chớp động bạch quang, nơi Tống Ngọc tỉnh lại sau khi bị bắt.","detail":"Tống Ngọc tỉnh lại tại đây và định vận dụng pháp lực hộ thân, nhưng lập tức kinh hãi rồi mềm nhũn ngã xuống. Công dụng của các cột đá và nguyên nhân trạng thái bất thường của nàng chưa được làm rõ.","theLucLienQuan":[],"nguon":["@c1172"]},{"id":"dong-quat-bi-mat-trong-truy-ma-coc","name":"Động quật bí mật trong Trụy Ma Cốc","cn":"","capDo":"khac","parentId":"truy-ma-coc","blurb":"Động quật bí mật được Mộc Linh Anh dùng làm nơi giam giữ Mộ Phái Linh, Tống Ngọc và Liễu Ngọc.","detail":"Nơi này có pháp trận phóng hắc khí gây mê và được che giấu kín đáo đến mức Mộc Linh Anh tin rằng ngay cả Hàn Lập tự mình tìm tới cũng khó phát hiện.","theLucLienQuan":[],"nguon":["@c1173"]},{"id":"huyen-vu-dai-dien","name":"Huyền Vũ đại điện","cn":"","capDo":"khac","parentId":"thai-chan-mon","blurb":"Đại điện bên trong Thái Chân Môn.","detail":"Nơi chưởng môn Thái Chân Môn đọc thư mời của Lạc Vân Tông và ra lệnh chuyển ngọc giản tới các trưởng bối ở Kim Hà Cốc.","theLucLienQuan":["Thái Chân Môn"],"nguon":["@c1174"]},{"id":"kim-ha-coc","name":"Kim Hà Cốc","cn":"","capDo":"vuc","parentId":"thai-chan-mon","blurb":"Khu vực phía sau núi thuộc Thái Chân Môn.","detail":"Nơi thái công trưởng lão và các sư tổ của Thái Chân Môn được hỏi ý kiến về việc có đích thân dự đại điển của Lạc Vân Tông hay không.","theLucLienQuan":["Thái Chân Môn"],"nguon":["@c1174"]},{"id":"thien-duong-dam","name":"Thiên Dương Đàm","cn":"","capDo":"khac","parentId":null,"blurb":"Cấm địa của Hợp Hoan Tông, quanh năm phủ sương xám.","detail":"Khu vực rộng vài trăm trượng, là nơi Hợp Hoan Lão Ma ẩn cư; ngay cả trưởng lão Nguyên Anh của Hợp Hoan Tông cũng không dám tùy tiện tiến vào.","theLucLienQuan":["Hợp Hoan Tông"],"nguon":["@c1174"]},{"id":"lung-linh-son","name":"Lung linh sơn","cn":"","capDo":"khac","parentId":"bac-luong-quoc","blurb":"Một ngọn núi tại Bắc Lương quốc.","detail":"Nơi nữ tử mang âm hàn chi khí và lão giả béo Hoàng Phong Cốc bàn cách nối lại giao tình với Hàn Lập trước đại điển.","theLucLienQuan":["Hoàng Phong Cốc"],"nguon":["@c1174"]},{"id":"bac-luong-quoc","name":"Bắc Lương quốc","cn":"","capDo":"quoc-gia","parentId":"thien-nam","blurb":"Quốc gia nơi Hoàng Phong Cốc và sáu phái đang hoạt động.","detail":"Sự ổn định của các phái tại đây chịu ảnh hưởng bởi việc Hoàng Phong Cốc không còn tu sĩ Nguyên Anh tọa trấn sau khi Từ Lệnh Hồ tọa hóa.","theLucLienQuan":["Hoàng Phong Cốc"],"nguon":["@c1174"]},{"id":"that-linh-dao","name":"Thất Linh Đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Nơi Ngụy Vô Nhai trở về sau cuộc trò chuyện với Chí Dương thượng nhân.","detail":"Ngụy Vô Nhai bay về Thất Linh Đảo sau khi tiết lộ đại hạn và đưa ra lời khuyên có thể là lần cuối dành cho Chí Dương.","theLucLienQuan":[],"nguon":["@c1175"]},{"id":"khe-quoc","name":"Khê Quốc","cn":"","capDo":"quoc-gia","parentId":"thien-nam","blurb":"Quốc gia tại Thiên Nam, nơi Lạc Vân Tông bành trướng mạnh sau khi uy danh của Hàn Lập được xác lập.","detail":"Trong vài tháng, Lạc Vân Tông chiếm hơn phân nửa Khê Quốc, khiến nhiều tông môn phải quy thuận hoặc rời khỏi quốc gia này.","theLucLienQuan":["Lạc Vân Tông","Cổ Kiếm Môn","Bách Xảo Viện"],"nguon":["@c1175"]},{"id":"van-mong-son","name":"Vân Mộng Sơn","cn":"","aliases":["Vân Mộng Sơn Mạch"],"capDo":"vuc","parentId":"khe-quoc","blurb":"Sơn mạch đặt cơ nghiệp của Lạc Vân Tông, Cổ Kiếm Môn và Bách Xảo Viện.","detail":"Địa thế Vân Mộng Sơn Mạch giúp Cổ Kiếm Môn và Bách Xảo Viện bảo lưu cơ nghiệp khi Lạc Vân Tông bành trướng khắp Khê Quốc.","theLucLienQuan":["Lạc Vân Tông","Cổ Kiếm Môn","Bách Xảo Viện"],"nguon":["@c1175"]},{"id":"tu-mau-phong-dong-phu","name":"Tử Mẫu Phong động phủ","cn":"","capDo":"khac","parentId":"tu-mau-phong","blurb":"Động phủ của Hàn Lập tại Tử Mẫu Phong.","detail":"Trong mật thất của động phủ, Hàn Lập bố trí pháp trận sinh hỏa diễm xanh trắng để tiếp tục luyện chế Phong Lôi Sí.","theLucLienQuan":["Lạc Vân Tông"],"nguon":["@c1175"]},{"id":"cuu-linh-son","name":"Cửu Linh Sơn","cn":"","capDo":"vuc","parentId":"linh-gioi","blurb":"Địa vực tại Linh Giới gắn với Phần Thiên yêu vương.","detail":"Thiên Lan Thánh Thú phân thân nhắc tới Phần Thiên yêu vương ở Cửu Linh Sơn khi giải thích khả năng dị biến thần thông của huyết mạch yêu thú.","theLucLienQuan":[],"nguon":["@c1176"]},{"id":"noi-khu-lac-van-tong","name":"Nội khu Lạc Vân Tông","cn":"","capDo":"khac","parentId":"lac-van-tong-son-mon","blurb":"Khu vực bên trong Lạc Vân Tông, nơi có lầu các dùng để kiểm kê vật liệu và tiếp nhận truyền tin.","detail":"Tại một lầu các trên ngọn núi trong nội khu, các quản sự Trúc Cơ kỳ đang kiểm kê vật liệu thì nhận được hồng quang mang ngọc giản cùng lệnh bài.","theLucLienQuan":["Lạc Vân Tông"],"nguon":["@c1176"]},{"id":"khong-gian-tiet-diem","name":"Không gian tiết điểm","cn":"","capDo":"khac","parentId":null,"blurb":"Con đường không gian Hàn Lập dự định sử dụng để tiến vào Linh Giới.","detail":"Phá Diệt Pháp Mục có khả năng làm suy yếu cách giới lực, vì vậy có thể hỗ trợ Hàn Lập khi đi qua không gian tiết điểm.","theLucLienQuan":[],"nguon":["@c1176","@c1233"]},{"id":"mau-phong-son","name":"Mẫu Phong Sơn","cn":"","capDo":"khac","parentId":"van-mong-son","blurb":"Ngọn núi có động phủ nơi Hàn Lập kiểm tra vật liệu và cô đọng Hỏa Linh Ti.","detail":"Sau khi nhận đủ vật liệu do Lạc Vân Tông thu gom, Hàn Lập tiến hành quá trình luyện khí kéo dài hai tháng tại động phủ trên Mẫu Phong Sơn.","theLucLienQuan":["Lạc Vân Tông"],"nguon":["@c1177"]},{"id":"dong-du-quoc","name":"Đông Dụ Quốc","cn":"","capDo":"quoc-gia","parentId":null,"blurb":"Quốc gia có Xương Châu, nơi diễn ra một cuộc gặp bí ẩn giữa sáu tu sĩ.","detail":"Hơn một tháng sau khi Hàn Lập rời Lạc Vân Tông, ba huynh đệ mang phi xoa tới một ngọn núi vô danh tại Xương Châu thuộc Đông Dụ Quốc để gặp nhóm Hậu lão ca.","theLucLienQuan":[],"nguon":["@c1177"]},{"id":"khe-bang-khong-lo-trong-noi-coc","name":"Khe băng khổng lồ trong nội cốc","cn":"","capDo":"khac","parentId":"noi-coc-truy-ma-coc","blurb":"Khe băng lớn nằm trên tuyến đường tiến sâu vào nội cốc Trụy Ma Cốc. Hàn Lập tới đây sau hơn nửa ngày vượt qua ngoại cốc.","detail":"Đây là điểm Hàn Lập trực tiếp tiến vào khi bắt đầu cuộc tìm kiếm nhóm Bạch Dao Di tại khu vực sâu của nội cốc.","theLucLienQuan":[],"nguon":["@c1178"]},{"id":"bang-phung","name":"Băng phùng","cn":"","capDo":"khac","parentId":"noi-coc-truy-ma-coc","blurb":"Khe băng trong nội cốc mà Hàn Lập rời khỏi trước khi bắt đầu tìm kiếm tam nữ.","detail":"Sau khi phi độn ra khỏi băng phùng, Hàn Lập triển khai linh trùng và thần thức để rà soát khu vực nội cốc.","theLucLienQuan":[],"nguon":["@c1179"]},{"id":"dai-son-co-dau-vet-hai-linh-duoc","name":"Đại sơn có dấu vết hái linh dược","cn":"","capDo":"khac","parentId":"noi-coc-truy-ma-coc","blurb":"Ngọn núi nơi Hàn Lập xác nhận tam nữ từng dừng lại hái linh dược sau khi tiến vào nội cốc.","detail":"Dấu vết lưu lại tại đây cho thấy tam nữ đã vào nội cốc, nhưng Hàn Lập không xác định được hướng họ tiếp tục di chuyển.","theLucLienQuan":[],"nguon":["@c1179"]},{"id":"bon-dia-ho-dung-nham","name":"Bồn địa hồ dung nham","cn":"","capDo":"khac","parentId":"noi-coc-truy-ma-coc","blurb":"Bồn địa hoang vắng có hồ dung nham đỏ rực, nơi Huyết Nguyệt dừng lại và chỉ xuống bên dưới.","detail":"Bồn địa chỉ nổi bật hai màu đen và đỏ, với hồ dung nham cực nóng ở trung tâm. Phản ứng của huyết quang cho thấy mục tiêu Hàn Lập truy tìm đang ẩn dưới hồ.","theLucLienQuan":[],"nguon":["@c1179"]},{"id":"dia-dao-duoi-day-ho","name":"Địa đạo dưới đáy hồ","cn":"","capDo":"khac","parentId":"bon-dia-ho-dung-nham","blurb":"Địa đạo thiên nhiên ẩn sau quang mạc cấm chế dưới đáy hồ dung nham.","detail":"Thông đạo gồ ghề kéo dài khoảng năm, sáu dặm rồi hướng lên một hang đá ngầm dẫn tới nơi giam giữ ba nữ tu.","theLucLienQuan":[],"nguon":["@c1180"]},{"id":"dong-quat-giam-giu-ba-nu-tu","name":"Động quật giam giữ ba nữ tu","cn":"","capDo":"khac","parentId":"dia-dao-duoi-day-ho","blurb":"Hang đá ngầm gồm nhiều khoang, là nơi ba nữ tu bị giam giữ.","detail":"Khoang trong của động quật bị hắc vụ bao phủ và có Mê Huyễn Chi trận tại trung tâm. Mộ Phái Linh, Liễu Ngọc và Tống Ngọc được Hàn Lập tìm thấy trong trạng thái bất tỉnh tại đây.","theLucLienQuan":[],"nguon":["@c1180"]},{"id":"van-truong-ma-uyen","name":"Vạn Trượng Ma Uyên","cn":"","aliases":["Ma Uyên"],"capDo":"khac","parentId":null,"blurb":"Ma uyên có ma khí tinh thuần, thích hợp để thi triển Ma Khí Quán Thể. Đệ nhị Nguyên Anh đang ẩn náu và hấp thu ma khí tại đây.","detail":"Vạn Trượng Ma Uyên trở thành đích truy đuổi tiếp theo của Hàn Lập sau khi hắn suy luận từ thân thể Thiên Sát Ma Thi, Huyền Âm Đại Pháp và nhu cầu tăng tiến tu vi của phân hồn.","theLucLienQuan":[],"nguon":["@c1181"]},{"id":"noi-coc","name":"Nội Cốc","cn":"","capDo":"khac","parentId":"truy-ma-coc","blurb":"Khu vực bên trong Trụy Ma Cốc được Hàn Lập dùng hàng vạn Phệ Kim Trùng tảo quét.","detail":"Hàn Lập không tìm thấy đệ nhị Nguyên Anh tại Nội Cốc nhưng thu được một số Cổ Bảo. Nhiều động phủ thượng cổ trong khu vực đã bị vét sạch, khiến hắn kết luận đối phương phần lớn đã rời đi.","theLucLienQuan":[],"nguon":["@c1181"]},{"id":"linh-miet-dao","name":"Linh Miết Đảo","cn":"","capDo":"khac","parentId":"that-linh-dao","blurb":"Một hòn đảo thuộc Thất Linh Đảo, hiện do Lạc Vân Tông quản lý và bố trí lực lượng đồn trú.","detail":"Trước khi tiến vào Vạn Trượng Ma Uyên, Hàn Lập ghé Linh Miết Đảo để liên hệ lực lượng Lạc Vân Tông. Hắn phát hiện hai nơi đóng quân và triệu tập hai đội tu sĩ tới gặp.","theLucLienQuan":["Lạc Vân Tông"],"nguon":["@c1181"]},{"id":"cua-vao-van-truong-ma-uyen","name":"Cửa vào Vạn Trượng Ma Uyên","cn":"","capDo":"khac","parentId":"van-truong-ma-uyen","blurb":"Lối vào Vạn Trượng Ma Uyên được phong kín bởi quang mạc hình thành từ mười cột đá quanh một xoáy nước lớn.","detail":"Xoáy nước tại cửa vực rộng khoảng năm sáu chục trượng và được mười cột đá nửa nổi nửa chìm bao quanh. Linh quang từ các cột tạo thành bạch sắc quang mạc có khả năng tự khép lại sau khi Hàn Lập dùng Tam Diễm Phiến mở khe tiến vào.","theLucLienQuan":["Lạc Vân Tông","Xích Liên Tông"],"nguon":["@c1182"]},{"id":"van-mong-son-trach","name":"Vân Mộng Sơn Trạch","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực mà Hàn Lập trở về hơn mười ngày sau khi bắt giữ đệ nhị Nguyên Anh. Tử Mẫu Phong và sơn môn Lạc Vân Tông nằm trong phạm vi này.","detail":"Sau khi xử lý biến cố tại Ma Uyên, Hàn Lập trở lại Vân Mộng Sơn Trạch nhưng không vào sơn môn Lạc Vân Tông. Hắn đi thẳng tới động phủ tại Tử Mẫu Phong.","theLucLienQuan":["Lạc Vân Tông"],"nguon":["@c1184"]},{"id":"hoang-dia-giao-gioi-khe-quoc-hoa-vu-quoc","name":"Hoang địa giao giới Khê Quốc–Hoa Vũ Quốc","cn":"","capDo":"khac","parentId":null,"blurb":"Vùng hoang địa được Hàn Lập chọn làm nơi Thiên Lan thánh thú tiến hành hoá hình lôi kiếp.","detail":"Khu vực nằm tại giao giới Khê Quốc và Hoa Vũ Quốc, có đất vàng cùng đá xám trắng, không có cây cỏ hoặc bóng người trong phạm vi hai, ba vạn dặm. Địa thế hoang vắng giúp hạn chế người ngoài phát hiện và can thiệp vào quá trình độ kiếp.","theLucLienQuan":[],"nguon":["@c1187"]},{"id":"phap-tran-do-kiep","name":"Pháp trận độ kiếp","cn":"","capDo":"khac","parentId":"thien-nam","blurb":"Khu vực trung tâm nơi Thiên Lan thánh thú chống liên hoàn thiên lôi.","detail":"Điện võng do lôi kiếp tạo ra bao phủ phạm vi mười dặm quanh pháp trận, khiến Hàn Lập đứng bên ngoài cũng bị cuốn vào ảnh hưởng. Cấm chế quanh pháp trận lần lượt bị thiên lôi phá hủy khi uy lực các đợt sét không ngừng tăng lên.","theLucLienQuan":["Thiên Lan"],"nguon":["@c1188"]},{"id":"trang-tron-giua-may-den","name":"Trăng tròn giữa mây đen","cn":"","capDo":"khac","parentId":null,"blurb":"Dị tượng trên không trung nhỏ linh dịch trắng xuống trong một chùm sáng bạc.","detail":"Quanh trăng tròn có cấm chế làm chậm những pháp khí tiếp cận. Dị tượng nhỏ xuống hai đợt linh dịch, tạo bạch quang có thể được Thiên Lan thánh thú phân thân hấp thu, rồi biến mất sau khi ba pháp khí của Hàn Lập tiến vào.","theLucLienQuan":[],"nguon":["@c1190"]},{"id":"lac-van-son-mach","name":"Lạc Vân sơn mạch","cn":"","capDo":"vuc","parentId":"van-mong-son","blurb":"Khu vực thuộc Vân Mộng Sơn được dùng làm nơi tổ chức song tu đại điển của Hàn Lập và Nam Cung Uyển.","detail":"Trong nhiều ngày diễn ra đại điển, hơn nửa bầu trời phía trên Lạc Vân sơn mạch được ngũ sắc quang hà bao phủ. Lầu các tạm dựng, linh hoa và linh mộc khiến khu vực được trang hoàng như tiên cảnh.","theLucLienQuan":["Lạc Vân Tông","Vân Mộng Sơn tam tông"],"nguon":["@c1192"]},{"id":"van-mong-son-mach","name":"Vân Mộng sơn mạch","cn":"","capDo":"vuc","parentId":"thien-nam","blurb":"Sơn mạch nơi Lạc Vân Tông tọa lạc. Sau khi rời khỏi nơi đây, ba người Quỷ Linh Môn bàn bạc việc xử lý Vương Thiền và thanh trừ Vương gia.","detail":"Ba người Quỷ Linh Môn rời Lạc Vân Tông rồi bay khỏi Vân Mộng sơn mạch. Trên đường trở về, họ quyết định giao cho Hoàng bào đại hán xử lý thế lực Vương gia và bàn kế hoạch đóng cửa tông môn.","theLucLienQuan":["Lạc Vân Tông","Quỷ Linh Môn"],"nguon":["@c1194"]},{"id":"cam-dia-hop-hoan-tong","name":"Cấm địa Hợp Hoan Tông","cn":"","capDo":"khac","parentId":"thien-nam","blurb":"Cấm địa bị sương mù xám dày đặc bao phủ thuộc Hợp Hoan Tông. Sâu bên trong có một bóng người ngồi trên cự thạch và theo dõi âm mưu liên quan đến Tụ Linh Châu.","detail":"Khu vực này nằm trong địa bàn Hợp Hoan Tông và bị sương mù màu xám nồng đậm bao phủ. Một bóng người thần bí ngồi sâu trong cấm địa, biết dị bảo đã tới tay Hàn Lập và ám chỉ hậu họa khi hắn đột phá bình cảnh Hóa Thần.","theLucLienQuan":["Hợp Hoan Tông"],"nguon":["@c1194"]},{"id":"quy-tan-lau","name":"Quý Tân Lầu","cn":"","capDo":"khac","parentId":"thien-nam","blurb":"Lầu các nơi Hàn Lập xem xét ba bảo vật và trao đổi với Thiên Lan thánh thú phân thân.","detail":"Tại đây, Hàn Lập biết được hậu họa của Tụ Linh Châu, phương pháp chuyển hóa nó thành Mộc Sinh Châu và cân nhắc nghi án liên quan đến Quỷ Linh Môn.","theLucLienQuan":[],"nguon":["@c1195"]},{"id":"lau-cac-noi-ham-van-chi-va-dong-huyen-nhi-cho","name":"Lầu các nơi Hạm Vân Chi và Đổng Huyên Nhi chờ","cn":"","capDo":"khac","parentId":"thien-nam","blurb":"Tòa lầu gần Quý Tân Lầu, nơi Hạm Vân Chi và Đổng Huyên Nhi chờ gặp Hàn Lập.","detail":"Hàn Lập đến đây sau khi rời Quý Tân Lầu và gặp lại hai nữ tu quen biết.","theLucLienQuan":["Hợp Hoan Tông"],"nguon":["@c1195"]},{"id":"dai-hap-coc","name":"Đại Hạp Cốc","cn":"","capDo":"khac","parentId":"viet-quoc","blurb":"Đại hạp cốc tại Việt Quốc có một mỏ linh thạch gần cạn do đệ tử Ngự Linh Tông trông coi.","detail":"Trong động quật sâu dưới mỏ có vị trí đầu thượng cổ Truyền Tống Trận nối với Loạn Tinh Hải. Hàn Lập bí mật xâm nhập bằng Thổ Độn Thuật và dựng lại trận tại đây.","theLucLienQuan":["Ngự Linh Tông"],"nguon":["@c1198"]},{"id":"tich-hai","name":"Tịch Hải","cn":"","capDo":"vuc","parentId":"loan-tinh-hai","blurb":"Một vùng biển được dùng làm mốc thời gian cho cuộc đại chiến giữa nhân loại và yêu thú.","detail":"Đại chiến trên hơn mười đảo ngoại hải bùng nổ hoàn toàn không lâu sau khi Hàn Lập rời Tịch Hải.","theLucLienQuan":[],"nguon":["@c1199"]},{"id":"tong-dan-nghich-tinh-minh","name":"Tổng đàn Nghịch Tinh Minh","cn":"","capDo":"khac","parentId":"loan-tinh-hai","blurb":"Căn cứ trung tâm của Nghịch Tinh Minh, từng bị Thiên Tinh Song Thánh tập kích.","detail":"Thiên Tinh Song Thánh giết nhiều tu sĩ Nguyên Anh tại đây rồi tự bạo Nguyên Từ Thần Quang. Vụ nổ biến hơn nửa tổng đàn thành tro tàn và giết nhiều cường giả của cả hai phía.","theLucLienQuan":["Nghịch Tinh Minh","Tinh Cung"],"nguon":["@c1199"]},{"id":"cac-dao-phu-can-thien-tinh-thanh","name":"Các đảo phụ cận Thiên Tinh Thành","cn":"","capDo":"khac","parentId":"thien-tinh-thanh","blurb":"Những hòn đảo quanh Thiên Tinh Thành đang trở thành nơi tập kết lực lượng trước trận quyết chiến.","detail":"Đại quân Nghịch Tinh Minh, tán tu và thám tử của nhiều phe cùng xuất hiện tại khu vực này, khiến hải vực quanh thành ngày càng hỗn loạn.","theLucLienQuan":["Nghịch Tinh Minh","Tinh Cung"],"nguon":["@c1199"]},{"id":"thien-tinh-thanh","name":"Thiên Tinh thành","cn":"","aliases":["Tinh Thành"],"capDo":"thanh","parentId":"loan-tinh-hai","blurb":"Trung tâm của Tinh Cung và là mục tiêu bao vây của Nghịch Tinh Minh.","detail":"Thiên Tinh thành là một đại thành có thể tập trung hàng vạn tu sĩ. Nghịch Tinh Minh tuyên bố đã bao vây nơi này, nhưng quy mô của thành khiến Hàn Lập nghi ngờ khả năng phong tỏa hoàn toàn bằng nhân lực thông thường.","theLucLienQuan":["Tinh Cung","Nghịch Tinh Minh"],"nguon":["@c1200"]},{"id":"hai-vuc-gan-thien-tinh-thanh","name":"Hải vực gần Thiên Tinh thành","cn":"","capDo":"khac","parentId":"loan-tinh-hai","blurb":"Vùng biển nơi Nghịch Tinh Minh bố trí lực lượng chặn viện quân tiến về Thiên Tinh thành.","detail":"Đoàn tu sĩ Bạch Thủy Kiếm Tông bị phục kích tại khu vực này bằng những cột sáng bắn lên từ mặt biển. Hàn Lập xuất hiện tại đây, giải cứu ba người sống sót và tra hỏi toán tu sĩ Nghịch Tinh Minh.","theLucLienQuan":["Nghịch Tinh Minh","Bạch Thủy Kiếm Tông","Tinh Cung"],"nguon":["@c1200"]},{"id":"nhan-gioi","name":"Nhân Giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện được dùng làm phạm vi xác định tính độc nhất của Nguyên Từ Sơn.","detail":"Hàn Lập nhận định trong toàn Nhân Giới không thể tìm được một Nguyên Từ Sơn thứ hai, vì vậy ngọn núi có giá trị đặc biệt đối với kế hoạch tu luyện Nguyên Từ Thần Quang.","theLucLienQuan":[],"nguon":["@c1200"]},{"id":"vung-bien-ngoai-thien-tinh-thanh","name":"Vùng biển ngoài Thiên Tinh thành","cn":"","capDo":"vuc","parentId":"noi-hai","blurb":"Vùng biển quanh tuyến phong tỏa Thiên Tinh thành, có nhiều bãi đá ngầm và vị trí mai phục dưới mặt nước.","detail":"Nghịch Tinh Minh bố trí nhiều toán tu sĩ tại các bãi đá ngầm và dưới mặt biển nhằm chặn giết những người lọt khỏi vòng vây. Hàn Lập dùng ẩn độn thuật vượt qua khu vực mà không bị phát hiện.","theLucLienQuan":["Nghịch Tinh Minh","Tinh Cung"],"nguon":["@c1201"]},{"id":"mat-bien-truoc-cu-dao-thien-tinh-thanh","name":"Mặt biển trước cự đảo Thiên Tinh thành","cn":"","capDo":"khac","parentId":"vung-bien-ngoai-thien-tinh-thanh","blurb":"Khu vực mặt biển ngay trước cự đảo Thiên Tinh thành, nơi một số lượng lớn linh thuyền đang tập kết.","detail":"Nhiều linh thuyền có kích thước, kiểu dáng và vật liệu khác nhau bố trí tại đây. Hạm đội gồm thuyền làm từ linh mộc, mỹ ngọc và cả một thiết thuyền đen bóng.","theLucLienQuan":[],"nguon":["@c1201"]},{"id":"thien-thuy-dao","name":"Thiên Thụy đảo","cn":"","capDo":"khac","parentId":"loan-tinh-hai","blurb":"Một trong ba đại linh đảo của Vạn Pháp Môn tại Loạn Tinh Hải.","detail":"Thiên Thụy đảo có linh mạch phẩm chất cao cùng nhiều loại linh hoa, linh thảo. Vạn Thiên Minh hứa trao đảo cho Kim Liên Môn nếu chiến dịch đánh hạ Tinh Cung thành công.","theLucLienQuan":["Vạn Pháp Môn","Kim Liên Môn"],"nguon":["@c1202"]},{"id":"cu-dao-thien-tinh-thanh","name":"Cự đảo Thiên Tinh Thành","cn":"","capDo":"khac","parentId":"loan-tinh-hai","blurb":"Cự đảo nơi Thiên Tinh Thành tọa lạc, được Phong Hoả Thiên Tuyệt Trận bảo vệ.","detail":"Hàn Lập dùng toàn lực bay tới cự đảo, xuyên qua cấm chế của Phong Hoả Thiên Tuyệt Trận rồi quan sát cuộc công kích của Nghịch Tinh Minh nhằm vào Thiên Tinh Thành.","theLucLienQuan":["Tinh Cung","Nghịch Tinh Minh"],"nguon":["@c1203"]},{"id":"cua-thanh-thien-tinh-thanh","name":"Cửa thành Thiên Tinh Thành","cn":"","capDo":"khac","parentId":"thien-tinh-thanh","blurb":"Cửa thành nằm sau lam sắc quang mạc, do các tu sĩ Tinh Cung trấn giữ.","detail":"Hàn Lập dừng trước cửa thành để trình lệnh bài khách khanh và chờ xác nhận. Lăng Ngọc Linh đích thân tới nghênh đón, sau đó ra lệnh cho thủ vệ vận dụng trận kỳ và trận bàn mở cấm chế.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1203"]},{"id":"thanh-dien","name":"Thánh Điện","cn":"","capDo":"khac","parentId":"thanh-son","blurb":"Thanh thạch đại điện trên tầng cao nhất Thánh Sơn, từng là nơi tổ sư sáng lập Tinh Cung tu luyện.","detail":"Thánh Điện là trọng địa cấm ngoại nhân, có linh khí nồng đậm và được dùng làm nơi triệu tập hơn hai mươi trưởng lão Tinh Cung bàn việc đối phó Nghịch Tinh Minh.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1204"]},{"id":"thach-dien-tinh-cung","name":"Thạch Điện","cn":"","capDo":"khac","parentId":"thanh-dien","blurb":"Khu vực thuộc Tinh Cung Thánh Điện, nơi nhiều tu sĩ hiện diện trong cuộc gặp với Hàn Lập.","detail":"Hàn Lập không tiện trực tiếp ra tay tại đây nên chỉ âm thầm dùng thần niệm lưu ấn ký lên Tây Môn trưởng lão mà những tu sĩ khác không phát hiện.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1205"]},{"id":"cam-dia-tinh-cung","name":"Cấm địa Tinh Cung","cn":"","capDo":"khac","parentId":"thien-tinh-thanh","blurb":"Cấm địa của Tinh Cung, nơi đặt Nguyên Thần Linh Đăng của các nhân vật quan trọng.","detail":"Nguyên Thần Linh Đăng của Tây Môn trưởng lão được đặt tại đây. Việc ngọn đèn đột ngột tắt khiến đệ tử trông coi lập tức báo động cho các trưởng lão.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1205"]},{"id":"dong-phu-tay-mon-truong-lao","name":"Động phủ Tây Môn trưởng lão","cn":"","capDo":"khac","parentId":"thien-tinh-thanh","blurb":"Nơi ở của Tây Môn trưởng lão trong phạm vi thế lực Tinh Cung.","detail":"Sau khi Nguyên Thần Linh Đăng của Tây Môn trưởng lão tắt, các trưởng lão Tinh Cung tiến vào khám xét nhưng chỉ tìm thấy mật thất trống rỗng, không có người hoặc thi thể.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1205"]},{"id":"mat-tran-phong-hoa-thien-tuyet-tran","name":"Mắt trận Phong Hỏa Thiên Tuyệt Trận","cn":"","capDo":"khac","parentId":"thien-tinh-thanh","blurb":"Vị trí trọng yếu của Phong Hỏa Thiên Tuyệt Trận do Vạn Thiên Minh trực tiếp trấn giữ.","detail":"Đây là mục tiêu tiến công của đội gồm Hàn Lập, Lăng Ngọc Linh, Mã trưởng lão và Triệu trưởng lão. Hàn Lập nhận trách nhiệm đối phó riêng Vạn Thiên Minh tại đây.","theLucLienQuan":["Tinh Cung","Nghịch Tinh Minh"],"nguon":["@c1206"]},{"id":"ba-muoi-sau-phong-hoa-tru-trong-yeu","name":"Ba mươi sáu Phong Hỏa trụ trọng yếu","cn":"","capDo":"khac","parentId":"thien-tinh-thanh","blurb":"Ba mươi sáu trụ then chốt được chọn từ tổng số một trăm lẻ tám Phong Hỏa trụ của đại trận.","detail":"Tinh Cung chia các đội tu sĩ tiến công những trụ này. Chỉ cần phá quá nửa số trụ trọng yếu, Phong Hỏa Thiên Tuyệt Trận sẽ tự tan.","theLucLienQuan":["Tinh Cung","Nghịch Tinh Minh"],"nguon":["@c1206"]},{"id":"phong-hoa-tru","name":"Phong Hỏa trụ","cn":"","capDo":"khac","parentId":"thien-tinh-thanh","blurb":"Các cự trụ vận hành Phong Hỏa Thiên Tuyệt Trận quanh Thiên Tinh Thành. Đây cũng là khu vực quân Tinh Cung và Nghịch Tinh Minh trực tiếp hỗn chiến.","detail":"Một Phong Hỏa trụ cao hơn ba trăm trượng có tiểu sơn trên đỉnh, được Vạn Thiên Minh, Long tu sĩ và Khâu đạo hữu dùng làm nơi quan sát chiến trường.","theLucLienQuan":["Tinh Cung","Nghịch Tinh Minh"],"nguon":["@c1207"]},{"id":"tinh-hai","name":"Tinh Hải","cn":"","capDo":"vuc","parentId":null,"blurb":"Vùng biển nơi Thiên Tinh Thành và các thế lực Tinh Cung, Nghịch Tinh Minh hoạt động. Lăng Ngọc Linh muốn Hàn Lập đưa những người nàng gửi gắm rời khỏi đây nếu Tinh Cung thất bại.","detail":"Tinh Hải được nhắc tới như phạm vi cần rời bỏ để những người thân cận với Lăng Ngọc Linh tránh bị Nghịch Tinh Minh truy sát sau một thất bại của Tinh Cung.","theLucLienQuan":["Tinh Cung","Nghịch Tinh Minh"],"nguon":["@c1207"]},{"id":"phong-hoa-cu-tru","name":"Phong Hỏa cự trụ","cn":"","capDo":"khac","parentId":null,"blurb":"Cự trụ nằm tại trung tâm trận nhãn và chiến trường giữa Tinh Cung với Nghịch Tinh Minh.","detail":"Đại quân hai phe triển khai quanh Phong Hỏa cự trụ và hình thành thế giằng co, lấy nơi này làm tâm điểm chiến trường.","theLucLienQuan":["Tinh Cung","Nghịch Tinh Minh"],"nguon":["@c1208","@c1215"]},{"id":"ma-nghiet-dao","name":"Ma Nghiệt đảo","cn":"","capDo":"khac","parentId":"tinh-hai","blurb":"Nơi Lam thị Song ma ẩn cư nhiều năm trước khi tái xuất.","detail":"Lam thị Song ma sống ẩn tại Ma Nghiệt đảo trong nhiều năm, sau đó rời đảo theo lời mời của Vạn Thiên Minh để tham gia bảo vệ trận nhãn.","theLucLienQuan":["Lam thị Song ma"],"nguon":["@c1208"]},{"id":"ngoai-thien-tinh-thanh","name":"Ngoài Thiên Tinh Thành","cn":"","capDo":"khac","parentId":"thien-tinh-thanh","blurb":"Khu vực bên ngoài Thiên Tinh Thành nơi Tinh Cung và Nghịch Tinh Minh mở trận hỗn chiến.","detail":"Chiến trường trải rộng khoảng mười dặm. Các tu sĩ trung thấp giai tản ra bốn phía để tránh khu vực giao tranh trung tâm của tu sĩ Nguyên Anh.","theLucLienQuan":["Tinh Cung","Nghịch Tinh Minh"],"nguon":["@c1209"]},{"id":"vung-bien-cach-thien-tinh-thanh-gan-ngan-dam","name":"Vùng biển cách Thiên Tinh Thành gần ngàn dặm","cn":"","capDo":"khac","parentId":"tinh-hai","blurb":"Vùng biển vắng nơi Vạn Thiên Minh dẫn Hàn Lập tới để giao thủ riêng.","detail":"Theo kết quả dò xét bằng thần niệm của Hàn Lập, trong phạm vi một trăm dặm quanh nơi này không có người mai phục, cấm chế hay pháp trận.","theLucLienQuan":[],"nguon":["@c1209"]},{"id":"linh-gioi","name":"Linh Giới","cn":"","capDo":"gioi-dien","parentId":null,"blurb":"Giới diện nơi các phương pháp tạo Đan Linh căn, Khí Linh căn và con đường ngũ hành hợp nhất đã được biết đến.","detail":"Tu sĩ từ Nguyên Anh trở lên tại Linh Giới phải chịu thiên kiếp định kỳ. Nguyên Anh và Hóa Thần chịu Tiểu Thiên Kiếp mỗi ba trăm năm, còn Luyện Hư, Hợp Thể và Đại Thừa chịu Đại Thiên Kiếp mỗi ba nghìn năm; uy lực thiên kiếp tăng dần qua từng lần.","theLucLienQuan":[],"nguon":["@c1214"]},{"id":"dong-quat-chua-nguyen-tu-than-son","name":"Động quật chứa Nguyên Từ Sơn","cn":"","capDo":"khac","parentId":"thien-tinh-thanh","blurb":"Động quật khổng lồ bên trong Thiên Tinh Thành, nơi cất giữ Nguyên Từ Sơn.","detail":"Không gian phía sau Đại Môn rộng gần ngàn trượng, cao hơn trăm trượng và có vách đá xanh phát bạch quang. Nguyên Từ Sơn nằm ở chính giữa; sau khi Lăng Ngọc Linh rời đi, Hàn Lập đóng Ngọc Môn và dùng mê vụ che phủ toàn bộ động quật.","theLucLienQuan":["Tinh Cung"],"nguon":["@c1217"]},{"id":"mau-phong","name":"Mẫu Phong","cn":"","capDo":"khac","parentId":"tu-mau-phong","blurb":"Ngọn núi đặt động phủ nơi Hàn Lập bế quan trùng kích Hóa Thần.","detail":"Linh Vân nhiều lần cố hạ xuống Mẫu Phong nhưng bị một lực vô hình đẩy ngược, báo hiệu Hàn Lập chưa thể khống chế thiên địa nguyên khí và lần đột phá cuối cùng thất bại.","theLucLienQuan":["Lạc Vân Tông"],"nguon":["@c1220"]},{"id":"thuy-mau-phong","name":"Thủy Mẫu Phong","cn":"","capDo":"khac","parentId":"tu-mau-phong","blurb":"Nơi Điền Cầm Nhi và Thạch Kiên thường xuyên tiềm tu.","detail":"Theo nghiêm lệnh của Hàn Lập, Điền Cầm Nhi và Thạch Kiên dành phần lớn thời gian tu luyện tại ngọn núi này.","theLucLienQuan":["Lạc Vân Tông"],"nguon":["@c1220"]},{"id":"tieu-son-thanh","name":"Tiểu sơn thành","cn":"","capDo":"thanh","parentId":"dai-tan","blurb":"Một thành nhỏ tại Đại Tấn có lối vào bí mật dẫn tới Thiên Cơ điện.","detail":"Trong một ngõ nhỏ của thành có bức tường đá được pháp thuật che mắt và nhiều tầng cấm chế bảo vệ. Xuyên qua lối vào này sẽ tới không gian phong bế của Thiên Cơ Các.","theLucLienQuan":["Thiên Cơ Các"],"nguon":["@c1221"]},{"id":"thien-co-dien","name":"Thiên Cơ điện","cn":"","capDo":"khac","parentId":"tieu-son-thanh","blurb":"Cung điện xanh lơ lửng trong bí cảnh phong bế của Thiên Cơ Các.","detail":"Thiên Cơ điện nằm phía sau Đại Ngọc môn, trong một không gian phong bế rộng hơn mười dặm được nhiều tầng cấm chế che giấu. Khu vực xung quanh có cầu thang bạch ngọc, linh vụ, linh cầm cùng kỳ hoa dị thảo.","theLucLienQuan":["Thiên Cơ Các"],"nguon":["@c1221"]},{"id":"dai-ngoc-mon","name":"Đại Ngọc môn","cn":"","capDo":"khac","parentId":"thien-co-dien","blurb":"Cổng ngọc đồ sộ nằm trên lối dẫn tới Thiên Cơ điện.","detail":"Đại Ngọc môn cao hơn trăm trượng, nối với Thiên Cơ điện bằng cầu thang bạch ngọc. Hai hàng khôi lỗi kim khôi kim giáp đứng canh tại đây, còn Tào Phong Duy phụ trách trấn giữ trong lần Trương đạo hữu tới báo tin.","theLucLienQuan":["Thiên Cơ Các"],"nguon":["@c1221"]},{"id":"gioi-tu-khong-gian-cua-thien-co-dien","name":"Giới tử không gian của Thiên Cơ Điện","cn":"","capDo":"gioi-nho","parentId":"dai-tan","blurb":"Không gian độc lập chứa tổng điện Thiên Cơ Các.","detail":"Đây là một tự do không gian hiếm thấy, cứ sau vài năm lại tự động thay đổi vị trí nên người bình thường khó phát hiện. Bên trong có Thiên Cơ Điện cùng cấm chế hạn chế tu sĩ dưới Nguyên Anh kỳ phi hành.","theLucLienQuan":["Thiên Cơ Các"],"nguon":["@c1222"]},{"id":"thien-lan-thanh-dien","name":"Thiên Lan Thánh Điện","cn":"","capDo":"khac","parentId":"mo-lan-thao-nguyen","blurb":"Thánh điện của Đột Ngột tộc trên Mộ Lan thảo nguyên.","detail":"Thiên Lan Thánh Nữ và các đại tiên sư triệu tập những tu sĩ cao giai của Đột Ngột tộc tới đây bế quan khổ tu.","theLucLienQuan":["Đột Ngột tộc","Thiên Lan"],"nguon":["@c1222"]},{"id":"khong-gian-thien-co-cac","name":"Không gian Thiên Cơ Các","cn":"","capDo":"gioi-nho","parentId":null,"blurb":"Không gian đặt Thiên Cơ Điện cùng nhiều khu lầu các tinh mỹ của Thiên Cơ Các.","detail":"Ngoài vùng trời quanh Thiên Cơ Điện, mặt đất trong không gian này có nhiều lầu các tinh mỹ và người qua lại. Những người bên dưới đã được dặn trước nên không lộ diện trong lúc Hàn Lập và Nguyên Trí giao chiến.","theLucLienQuan":["Thiên Cơ Các"],"nguon":["@c1226"]},{"id":"vung-nui-vo-danh-giua-hoang-da-va-phong-chau","name":"Vùng núi vô danh giữa vùng hoang dã và quận Phong Châu","cn":"","capDo":"khac","parentId":"phong-chau","blurb":"Vùng núi nằm giữa miền hoang dã và quận Phong Châu, nơi lực lượng Huyết Cốt Môn bị tiêu diệt.","detail":"Sau cuộc vây giết đội xâm nhập, nơi này trở thành địa điểm Hàn Lập hiện thân chặn đường Phòng tông chủ.","theLucLienQuan":["Âm La Tông","Huyết Cốt Môn"],"nguon":["@c1227"]},{"id":"vung-phu-can-tong-dan-am-la-tong","name":"Vùng phụ cận tổng đàn Âm La Tông","cn":"","capDo":"khac","parentId":"phong-chau","blurb":"Khu vực quanh tổng đàn Âm La Tông được Hàn Lập bí mật giám thị trong khoảng nửa năm.","detail":"Hàn Lập theo dõi vùng này để nắm hành tung của Phòng tông chủ và chờ lúc đối phương rời tổng đàn một mình.","theLucLienQuan":["Âm La Tông"],"nguon":["@c1227"]},{"id":"tong-dan-am-la-tong","name":"Tổng đàn Âm La Tông","cn":"","capDo":"khac","parentId":null,"blurb":"Trung tâm của Âm La Tông, hiện chỉ còn năm sáu trưởng lão tọa trấn.","detail":"Sau khi sưu hồn Phòng tông chủ, Hàn Lập biết phần lớn trưởng lão đang ở bên ngoài ứng phó các thế lực đối địch. Hắn dự định tránh những cấm chế đáng ngại tại đây, đánh phủ đầu lực lượng trấn giữ rồi truy tìm các trưởng lão còn lại.","theLucLienQuan":["Âm La Tông"],"nguon":["@c1229"]},{"id":"noi-mon-am-la-tong","name":"Nội môn Âm La Tông","cn":"","capDo":"khac","parentId":"tong-dan-am-la-tong","blurb":"Khu vực bên trong tổng đàn Âm La Tông, nơi nhiều trưởng lão vẫn bị hại dù cao tầng đã truy xét và mở cấm chế.","detail":"Các vụ mất tích tiếp tục xảy ra ngay trong nội môn Âm La Tông. Việc cao tầng vận dụng cấm chế nhưng không tìm ra thủ phạm khiến các trưởng lão còn lại phải tập trung để tự bảo vệ.","theLucLienQuan":["Âm La Tông"],"nguon":["@c1231"]},{"id":"dia-ban-am-la-tong","name":"Địa bàn Âm La Tông","cn":"","capDo":"vuc","parentId":"dai-tan","blurb":"Lãnh địa do Âm La Tông kiểm soát tại Đại Tấn. Sau khi cao tầng tông môn tổn thất nặng, khu vực này bị nhiều tông môn đối địch đưa tu sĩ vào xâm lấn.","detail":"Âm La Tông từng có thế lực mạnh và gây thù với nhiều tông môn. Khi thực lực của họ suy yếu quá nửa, các đối thủ Chính–Ma phụ cận đồng loạt tiến vào lãnh địa và bắt đầu tranh đoạt.","theLucLienQuan":["Âm La Tông","Các tông môn phụ cận Âm La Tông"],"nguon":["@c1231"]},{"id":"hoac-chau","name":"Hoắc Châu","cn":"","capDo":"chau","parentId":"dai-tan","blurb":"Một khu vực hẻo lánh tại Đại Tấn, nơi các tu sĩ Luyện Khí kỳ tổ chức tỷ thí và nam tử có cánh xuất hiện trên không.","detail":"Người địa phương cho rằng Hoắc Châu hẻo lánh đến mức khó có yêu thú cao giai hiện thân. Tại một vùng núi hoang ở đây, hai nhóm tu sĩ trẻ chứng kiến cuộc đấu pháp giữa Thanh Linh Kiếm và phi đao đỏ lửa, sau đó hai người trong số họ phát hiện nam tử bí ẩn có con mắt thứ ba.","theLucLienQuan":["Lâm gia tại Hoắc Châu"],"nguon":["@c1231"]},{"id":"ba-khong-gian-tiet-diem","name":"Ba không gian tiết điểm đã tìm thấy","cn":"","capDo":"khac","parentId":null,"blurb":"Ba tiết điểm do nhóm Hướng Chi Lễ phát hiện đều chưa thể sử dụng an toàn.","detail":"Hai tiết điểm có không gian phong bạo ở cửa vào mạnh tới mức tu sĩ tiến vào chắc chắn tử vong. Tiết điểm còn lại có thể miễn cưỡng tiến vào nhưng quá bất ổn và có nguy cơ sụp đổ bất cứ lúc nào.","theLucLienQuan":[],"nguon":["@c1234"]},{"id":"khong-gian-tiet-diem-cua-xa-lao-yeu","name":"Không gian tiết điểm của Xa lão yêu","cn":"","capDo":"khac","parentId":null,"blurb":"Một tiết điểm có cửa vào bị không gian phong bạo cực mạnh bao phủ, hiện chỉ Xa lão yêu có thể sử dụng.","detail":"Hướng Chi Lễ và Hô đạo hữu từng trực tiếp khảo sát nhưng không thể vượt qua phong bạo tại cửa vào. Bản thể mạnh mẽ giúp Xa lão yêu có thể tiến vào nơi này.","theLucLienQuan":["Vạn Yêu Cốc"],"nguon":["@c1234"]},{"id":"vu-nguyet-son-mach","name":"Vụ Nguyệt Sơn mạch","cn":"","capDo":"vuc","parentId":"dai-tan","blurb":"Sơn mạch dài khoảng mười vạn dặm tại biên giới tây bắc Đại Tấn.","detail":"Vụ Nguyệt Sơn mạch nằm ở khu vực giao nhau giữa hai châu, có nhiều núi non hiểm trở và chứa Ma Đà Sơn.","theLucLienQuan":["Thiên Ma Tông","Ma cung"],"nguon":["@c1235"]},{"id":"ma-cung-dia-danh","name":"Ma cung","cn":"","capDo":"khac","parentId":"ma-da-son","blurb":"Quần thể cung điện, lầu các và đình đài hoa mỹ trên đỉnh Ma Đà Sơn.","detail":"Các kiến trúc được dựng bằng gỗ quý và mỹ ngọc hiếm có. Đại điện lớn nhất đang tổ chức tiệc chiêu đãi khoảng bảy tám khách quý trong lễ nạp thiếp.","theLucLienQuan":["Ma cung","Thiên Ma Tông"],"nguon":["@c1235","@c1236"]},{"id":"ma-da-son","name":"Ma Đà Sơn","cn":"","capDo":"khac","parentId":"dai-tan","blurb":"Ngọn núi đặt Ma cung của Hô Khánh Lôi. Khi Hàn Lập và hai tu sĩ Hóa Thần tới nơi, cả ngọn núi đang bị bão tuyết bao phủ.","detail":"Ma Đà Sơn chìm trong bão tuyết, nhưng quần thể cung điện của Ma cung bên dưới vẫn được cấm chế tạo thành tầng sáng vàng bảo vệ.","theLucLienQuan":["Thiên Ma Tông"],"nguon":["@c1236"]},{"id":"dai-dien-cua-ho-khanh-loi","name":"Đại điện của Hô Khánh Lôi","cn":"","capDo":"khac","parentId":"ma-cung-dia-danh","blurb":"Nơi Hô Khánh Lôi tổ chức tiệc nạp thiếp với sự tham dự của các tu sĩ Hóa Thần và nhiều khách nhân Nguyên Anh kỳ.","detail":"Trong đại điện, Hàn Lập được đối đãi ngang hàng với các tu sĩ Hóa Thần, công khai thừa nhận đã giết tông chủ Âm La Tông và cùng các khách nhân dâng lễ vật. Đây cũng là nơi Hàn Lập bất ngờ gặp lại Tử Linh trong thân phận thị thiếp của Hô Khánh Lôi.","theLucLienQuan":["Ma cung"],"nguon":["@c1237"]},{"id":"dai-dien-ma-cung-ho-khanh-loi","name":"Đại điện Ma cung","cn":"","capDo":"khac","parentId":"ma-cung-ho-khanh-loi-map","blurb":"Nơi diễn ra chén rượu đoạn tuyệt và cuộc đối đầu giữa Hàn Lập với Hô Khánh Lôi.","detail":"Đại điện thuộc Ma cung của Hô Khánh Lôi, nơi các tu sĩ Hóa Thần và Nguyên Anh dự hội. Tại đây, Hàn Lập can thiệp để cứu Tử Linh và thương lượng với Hô Khánh Lôi về điều kiện trả tự do cho nàng.","theLucLienQuan":["Ma cung của Hô Khánh Lôi","Thiên Ma Tông"],"nguon":["@c1238"]},{"id":"ma-cung-ho-khanh-loi-map","name":"Ma cung","cn":"","capDo":"khac","parentId":null,"blurb":"Cơ sở do Hô Khánh Lôi làm chủ, nơi Tử Linh bị giữ và nhiều tu sĩ đang dự hội.","detail":"Hô Khánh Lôi chuẩn bị nhận Tử Linh làm thị thiếp tại Ma cung và tuyên bố nàng không còn quyền tự quyết sau khi tiến vào đây. Đại điện bên trong là nơi lão đối đầu và thương lượng với Hàn Lập.","theLucLienQuan":["Ma cung của Hô Khánh Lôi","Thiên Ma Tông"],"nguon":["@c1238"]},{"id":"khoang-khong-ngoai-dai-dien-ma-cung","name":"Khoảng không ngoài đại điện Ma cung","cn":"","capDo":"khac","parentId":"dai-dien-ma-cung-ho-khanh-loi","blurb":"Khoảng không phía ngoài đại điện Ma cung, nơi Hàn Lập và Hô lão ma chuẩn bị thực hiện điều kiện một kích.","detail":"Hàn Lập và Hô lão ma huyền phù tại đây, cách mặt đất hơn trăm trượng. Các tu sĩ dự tiệc cùng người của Ma cung kéo ra quan sát, trong khi Hướng Chi Lễ và Phong lão quái tới giám sát.","theLucLienQuan":["Ma cung"],"nguon":["@c1240"]},{"id":"hoa-nguc","name":"Hoả Ngục","cn":"","capDo":"khac","parentId":"dai-tan","blurb":"Một trong thất đại cấm địa của Đại Tấn, nằm ở phía đông nam và kéo dài hàng nghìn dặm.","detail":"Hoả Ngục tồn tại từ thời thượng cổ, bên ngoài dày đặc núi lửa và tài liệu hỏa thuộc tính. Vùng núi trung tâm bị biển hồng vụ bao phủ mới là cấm địa thực sự, nơi rất ít tu sĩ có thể sống sót trở ra.","theLucLienQuan":[],"nguon":["@c1243"]},{"id":"bien-hong-vu-trung-tam-hoa-nguc","name":"Biển hồng vụ trung tâm Hoả Ngục","cn":"","capDo":"vuc","parentId":"hoa-nguc","blurb":"Vùng khói đỏ nguy hiểm nằm tại trung tâm Hoả Ngục, có khả năng áp chế thần niệm và tác động mạnh đến linh quang hộ thể.","detail":"Ngay cả thần niệm của tu sĩ Nguyên Anh hậu kỳ cũng bị hạn chế nghiêm trọng tại đây. Bên trong tồn tại yêu thú hỏa thuộc tính cấp sáu, cấp bảy cùng một mối nguy hiểm còn lớn hơn chưa được xác định.","theLucLienQuan":[],"nguon":["@c1243"]},{"id":"nui-lua-lo-lung-trong-hoa-nguc","name":"Núi lửa lơ lửng trong Hỏa Ngục","cn":"","capDo":"khac","parentId":"hoa-nguc","blurb":"Ngọn núi lửa khổng lồ lơ lửng giữa không trung, là mục tiêu Hàn Lập tìm đến sau ba ngày vượt qua hồng sắc vụ hải.","detail":"Tại miệng núi lửa, Hàn Lập đặt tế đàn noãn ngọc, triển khai Càn Lam Đỉnh và kích hoạt pháp trận tạo thành nhà lao bằng các cột sáng lam để phong kín không gian phụ cận.","theLucLienQuan":[],"nguon":["@c1244"]},{"id":"hoa-ho-trong-hoa-nguc","name":"Hỏa hồ","cn":"","capDo":"khac","parentId":"hoa-nguc","blurb":"Một khu vực nằm trên đường Hàn Lập tiến tới ngọn núi lửa mục tiêu.","detail":"Hỏa hồ liên tục phun ra những cột lửa có uy lực không nhỏ mà không có dấu hiệu báo trước, khiến Hàn Lập phải giảm độn tốc để né tránh và hạn chế hao phí pháp lực.","theLucLienQuan":[],"nguon":["@c1244"]},{"id":"mieng-nui-lua","name":"Miệng núi lửa","cn":"","capDo":"khac","parentId":"nui-lua-lo-lung-trong-hoa-nguc","blurb":"Trung tâm khu vực Hàn Lập bố trí cạm bẫy bắt Thái Dương Tinh Hỏa.","detail":"Thái Âm Hỏa Điểu tìm kiếm quanh miệng núi lửa rồi dẫn Thái Dương Tinh Hỏa rời khỏi dòng dung nham, bay lên phía pháp trận đã được chuẩn bị.","theLucLienQuan":[],"nguon":["@c1245"]},{"id":"vung-dung-nham-duoi-mat-dat","name":"Vùng dung nham dưới mặt đất","cn":"","capDo":"khac","parentId":"hoa-nguc","blurb":"Khu vực cực nhiệt bên dưới mặt đất, nơi Hàn Lập tìm kiếm Thái Dương Tinh Hỏa suốt một tháng.","detail":"Nhiệt độ tại đây hạn chế thần niệm của Hàn Lập xuống phạm vi không quá trăm trượng. Môi trường dung nham đồng thời cung cấp sức mạnh và lợi thế di chuyển cho Thái Dương Tinh Hỏa.","theLucLienQuan":[],"nguon":["@c1245"]},{"id":"long-giam-quang-tru","name":"Lồng giam quang trụ","cn":"","capDo":"khac","parentId":null,"blurb":"Khu vực mai phục dùng để vây bắt Thái Dương Tinh Hoả.","detail":"Lồng giam được dựng bằng nhiều quang trụ. Khi pháp trận phát động, ánh sáng từ các quang trụ kết thành quang võng để phong toả đường bay, còn mặt đất bên trong bị phủ lam băng nhằm ngăn mục tiêu thi triển độn thuật.","theLucLienQuan":[],"nguon":["@c1246"]},{"id":"duoc-vien-cua-han-lap","name":"Dược viện của Hàn Lập","cn":"","capDo":"khac","parentId":"van-mong-son","blurb":"Dược viện trồng Huyền Thiên Tiên Đằng, Cửu Khúc Linh Sâm và nhiều linh dược quý.","detail":"Huyền Thiên Tiên Đằng hồi sinh tại đây và mọc bám kín các cột đá bạch ngọc. Hàn Lập bố trí nhiều lớp cấm chế quanh tiên đằng trước khi rời đi.","theLucLienQuan":[],"nguon":["@c1248"]},{"id":"hoang-dao-co-long-lan-qua","name":"Hoang đảo có Long Lân Quả","cn":"","capDo":"khac","parentId":"ngoai-hai","blurb":"Hoang đảo tại Ngoại hải có cây Long Lân Quả mà Kim Giao Vương định kỳ đến thu hái.","detail":"Phong Hi đến hoang đảo để chuẩn bị di dời cây Long Lân Quả theo thỏa thuận với Kim Giao Vương. Hàn Lập bí mật theo dõi hai yêu tu tại đây nhưng bị bảo châu khuếch đại thần thức phát hiện, khiến cuộc giao chiến nổ ra.","theLucLienQuan":["Giao Long tộc"],"nguon":["@c1250"]},{"id":"hoang-dao","name":"Hoang đảo","cn":"","capDo":"khac","parentId":null,"blurb":"Hòn đảo nằm phía dưới chiến trường giữa Hàn Lập, Kim Giao Vương và Phong Hi.","detail":"Mười hai luồng bạch khí mang theo trợ thủ của Hàn Lập từ hoang đảo bay lên không trung và tiến vào chiến trường.","theLucLienQuan":[],"nguon":["@c1251"]},{"id":"vung-phu-can-ngoai-khoi","name":"Vùng phụ cận ngoài khơi","cn":"","capDo":"vuc","parentId":null,"blurb":"Khu vực ngoài khơi Hàn Lập tìm đến sau khi diệt Phong Hi và Kim Giao Vương.","detail":"Hàn Lập bay tới vùng này để tìm tiểu đảo có động quật cất giữ Long Lân Quả Linh Thụ.","theLucLienQuan":[],"nguon":["@c1252"]},{"id":"ngoai-coc","name":"Ngoại Cốc","cn":"","capDo":"khac","parentId":"truy-ma-coc","blurb":"Khu vực bên ngoài Trụy Ma Cốc, nơi cấm chế đã suy yếu gần như hoàn toàn.","detail":"Ngoại Cốc được mở cho tu sĩ bình thường tiến vào tìm bảo, nhưng phần lớn khoáng tài, linh thảo và linh mộc quý đã bị càn quét.","theLucLienQuan":[],"nguon":["@c1253"]},{"id":"son-coc-ky-bi","name":"Sơn cốc kỳ bí","cn":"","capDo":"khac","parentId":"noi-coc","blurb":"Sơn cốc kín đáo trong Nội Cốc, nơi Hàn Lập bố trí cơ sở phục vụ quá trình bế quan.","detail":"Nơi đây có động phủ bằng mỹ ngọc, Dược Viên rộng hơn trăm trượng, tầng tầng cấm chế và một Truyền Tống Trận cỡ nhỏ nối tới nơi tu luyện.","theLucLienQuan":[],"nguon":["@c1253"]},{"id":"truyen-tong-tran-toi-ngu-long-hai","name":"Truyền Tống Trận tới Ngũ Long Hải","cn":"","capDo":"khac","parentId":"dai-tan","blurb":"Tòa truyền tống trận có thể đưa người trực tiếp tới Ngũ Long Hải.","detail":"Nhóm Hướng Chi Lễ từng nắm được địa điểm của tòa truyền tống trận này, biến nó thành đầu mối để Hàn Lập tới hải vực có không gian tiết điểm.","theLucLienQuan":[],"nguon":["@c1254"]},{"id":"phien-hai-vu","name":"Phiến hải vụ","cn":"","capDo":"vuc","parentId":"ngu-long-hai","blurb":"Vùng sương trắng mênh mang che khuất tiểu đảo trấn thủ không gian tiết điểm.","detail":"Hàn Lập bay trong hải vụ khoảng nửa canh giờ trước khi dùng hai đạo kim hồ phá lớp che giấu, làm lộ khu vực trống trải cùng tiểu đảo.","theLucLienQuan":["Môn hạ Hướng Chi Lễ"],"nguon":["@c1255"]},{"id":"tieu-dao-tran-thu-khong-gian-tiet-diem","name":"Tiểu đảo trấn thủ không gian tiết điểm","cn":"","capDo":"khac","parentId":"phien-hai-vu","blurb":"Tiểu đảo nằm trong vùng hải vụ, có kiến trúc và người trấn thủ do Hướng Chi Lễ bố trí.","detail":"Ba tu sĩ Kết Đan phụng mệnh Hướng Chi Lễ trú đóng tại đây, chờ Hàn Lập và canh giữ không gian tiết điểm.","theLucLienQuan":["Môn hạ Hướng Chi Lễ"],"nguon":["@c1255"]},{"id":"vu-hai","name":"Vụ hải","cn":"","capDo":"vuc","parentId":"ngu-long-hai","blurb":"Vùng biển sương mù bao phủ tiểu đảo và cửa vào không gian tiết điểm.","detail":"Phượng tiên tử từ bên ngoài bay vào vụ hải rồi vô tình lọt vào hệ thống cấm chế phòng vệ quanh tiểu đảo.","theLucLienQuan":["Thiên Ma Tông","Thế lực môn nhân của Hàn Lập tại Loạn Tinh Hải"],"nguon":["@c1256"]},{"id":"thien-sa-dai-luc","name":"Thiên Sa Đại Lục","cn":"","capDo":"chau","parentId":"nhan-gioi","blurb":"Đại lục nơi Hàn Lập lấy Kim Thước Hoàn và bị hai tu sĩ Nguyên Anh truy đuổi.","detail":"Sau nhiều năm thu gom bảo vật, Hàn Lập tới Thiên Sa Đại Lục và lấy Kim Thước Hoàn khỏi trọng địa một tông môn. Hắn sau đó áp đảo hai tu sĩ Nguyên Anh truy đuổi trên một ngọn núi vô danh.","theLucLienQuan":["Tông môn sở hữu Kim Thước Hoàn"],"nguon":["@c1258"]},{"id":"vo-danh-cao-son","name":"Vô danh cao sơn","cn":"","capDo":"khac","parentId":"thien-sa-dai-luc","blurb":"Ngọn núi tại Thiên Sa Đại Lục nơi hai tu sĩ Nguyên Anh đuổi kịp Hàn Lập.","detail":"Trên đỉnh núi, Hàn Lập đề nghị dùng linh thạch đổi lấy Kim Thước Hoàn rồi giao đấu khi hai lão giả khước từ. Hắn tước quyền khống chế pháp bảo của họ, trả lại các món vừa thu và mang Kim Thước Hoàn rời đi.","theLucLienQuan":["Tông môn sở hữu Kim Thước Hoàn"],"nguon":["@c1258"]},{"id":"huyet-sac-cam-dia","name":"Huyết Sắc cấm địa","cn":"","capDo":"gioi-nho","parentId":"viet-quoc","blurb":"Cấm địa tại Việt Quốc, nơi có bảo tháp trung tâm và truyền thừa của một Thượng Cổ tu sĩ.","detail":"Nam Cung Uyển trở lại nơi này sau khi đạt Nguyên Anh hậu kỳ. Người muốn vào bảo tháp trung tâm phải có cấm chế lệnh bài để tránh bị cấm chế bên ngoài diệt sát.","theLucLienQuan":[],"nguon":["@c1260"]},{"id":"bao-thap-trung-tam-huyet-sac-cam-dia","name":"Bảo tháp trung tâm Huyết Sắc cấm địa","cn":"","capDo":"khac","parentId":"huyet-sac-cam-dia","blurb":"Bảo tháp nằm tại trung tâm Huyết Sắc cấm địa, lưu giữ y bát và bảo vật của Thượng Cổ tu sĩ.","detail":"Nam Cung Uyển dùng cấm chế lệnh bài tiến vào đây, nhận y bát của Thượng Cổ tu sĩ và phát hiện tàn cốt của một người từng tự tiện xông vào cấm chế. Trong số bảo vật bên cạnh tàn cốt có Lục Đinh Thiên Giáp Phù.","theLucLienQuan":[],"nguon":["@c1260"]},{"id":"hai-vu","name":"Hải vụ","cn":"","capDo":"vuc","parentId":"loan-tinh-hai","blurb":"Vùng sương biển nơi Băng Phượng xuất hiện trước chuyến vượt giới.","detail":"Băng Phượng bay ra từ vùng hải vụ dưới hình thái Băng Phượng tuyết trắng rồi hóa thành nữ tử áo bạc.","theLucLienQuan":[],"nguon":["@c1261"]},{"id":"han-nguyen","name":"Hàn Nguyên","cn":"","capDo":"khac","parentId":null,"blurb":"Nguồn băng hàn được Băng Phượng dùng để cô đọng Thiên Thuyền.","detail":"Băng Phượng cho biết Thiên Thuyền của nàng được cô đọng từ Hàn Nguyên qua hơn vạn năm; bản chất và vị trí cụ thể chưa được giải thích thêm.","theLucLienQuan":[],"nguon":["@c1261"]}]};
